// src/pages/QuantumCertificate.jsx
import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Award, Lock, ShieldCheck, Atom, Cpu, Sparkles, Code2 } from 'lucide-react';

/* ────────────────────────────────────────────────────────────
   كۋانت لوگو — ئاتوم شەكلىدىكى ئوربىتال نۇسخا (SVG، رەسىمسىز)
   ──────────────────────────────────────────────────────────── */
function QuantumMark({ size = 64, className = '' }) {
  return (
    <svg
      viewBox="0 0 100 100"
      width={size}
      height={size}
      className={className}
      fill="none"
    >
      <defs>
        <linearGradient id="qm-gold" x1="0%" y1="0%" x2="100%" y2="100%">
          <stop offset="0%" stopColor="#fde68a" />
          <stop offset="50%" stopColor="#d4a017" />
          <stop offset="100%" stopColor="#92660d" />
        </linearGradient>
      </defs>
      <circle cx="50" cy="50" r="48" stroke="url(#qm-gold)" strokeWidth="1.5" opacity="0.5" />
      <ellipse cx="50" cy="50" rx="40" ry="16" stroke="url(#qm-gold)" strokeWidth="2.5" transform="rotate(0 50 50)" />
      <ellipse cx="50" cy="50" rx="40" ry="16" stroke="url(#qm-gold)" strokeWidth="2.5" transform="rotate(60 50 50)" />
      <ellipse cx="50" cy="50" rx="40" ry="16" stroke="url(#qm-gold)" strokeWidth="2.5" transform="rotate(120 50 50)" />
      <circle cx="50" cy="50" r="6.5" fill="url(#qm-gold)" />
      <circle cx="90" cy="50" r="3.2" fill="url(#qm-gold)" />
      <circle cx="27" cy="83" r="3.2" fill="url(#qm-gold)" />
      <circle cx="27" cy="17" r="3.2" fill="url(#qm-gold)" />
    </svg>
  );
}

/* ────────────────────────────────────────────────────────────
   ئىقتىدار سىنبەلگىلىرى خەرىتىسى
   ──────────────────────────────────────────────────────────── */
const ICONS = { atom: Atom, sparkles: Sparkles, cpu: Cpu, code: Code2 };

export default function QuantumCertificate({ isEligible, data }) {
  // تىل ھالىتى: 'ug' (ئۇيغۇرچە ئاساس + ئېنگلىزچە قوشۇمچە), 'en' (پەقەت ئېنگلىزچە)
  const [lang, setLang] = useState('ug');
  // تاللانغان گۇۋاھنامە ID ھالىتى
  const [selectedCertId, setSelectedCertId] = useState('C-901');

  // ئۆلچەملىك گۇۋاھنامە سانلىق مەلۇماتلىرى
  const defaultCerts = [
    {
      id: "C-901",
      titleUg: "يۆنىلىشلىك كۋانت ئاساسلىرى ئىنژېنېرى گۇۋاھنامىسى",
      titleEn: "Quantum Foundations Certified Engineer",
      issuerUg: "ئۇيغۇر كۋانت سۈنئىي ئەقىل مەركىزى",
      issuerEn: "Uyghur Quantum AI Center",
      reqLessons: 3,
      reqExercises: 2,
      status: "ئېرىشكەن",
      isUnlocked: true,
      certNo: "UQAI-QF-2025-00901",
      issueDateUg: "2025-يىل 20-دىكابىر",
      issueDateEn: "December 20, 2025",
      verifyCode: "8F3A-9D21",
      competencies: [
        { icon: "atom", ug: "كۋانت دەرۋازىلىرى ۋە زانجىرلار", en: "Quantum Gates & Circuits" },
        { icon: "sparkles", ug: "ئۈستىمۇ-ئۈستى چۈشۈش ۋە چىرمىشىش", en: "Superposition & Entanglement" },
        { icon: "cpu", ug: "كۋانت سىممۇلياتور قۇرۇلمىسى", en: "Quantum Circuit Simulation" },
        { icon: "code", ug: "كۋانت سۈنئىي ئەقىل ئالگورىزىمى", en: "Quantum AI Algorithm Design" },
      ],
    },
    {
      id: "C-902",
      titleUg: "ئالىي دەرىجىلىك كۋانت سۈنئىي ئەقىل ۋە كۋانت ماشىنا ئۆگىنىشى مۇتەخەسسىسى",
      titleEn: "Advanced Quantum AI & Machine Learning Specialist",
      issuerUg: "ئۇيغۇر كۋانت سۈنئىي ئەقىل تەجرىبىخانىسى",
      issuerEn: "Uyghur Quantum AI Lab",
      reqLessons: 7,
      reqExercises: 6,
      status: "قۇلۇپلاقلىق",
      isUnlocked: false,
      certNo: "UQAI-AQ-2025-00902",
      issueDateUg: "2026-يىل 14-ئاپرىل",
      issueDateEn: "April 14, 2026",
      verifyCode: "2C7E-114B",
      competencies: [
        { icon: "atom", ug: "كۋانت بىت تور قۇرۇلمىسى", en: "Multi-Qubit Architecture" },
        { icon: "sparkles", ug: "دىكوگېرانس باشقۇرۇش", en: "Decoherence Mitigation" },
        { icon: "cpu", ug: "ئۆزگىرىشچان كۋانت زانجىرى", en: "Variational Quantum Circuits" },
        { icon: "code", ug: "QML مودېلىنى ئىجرا قىلىش", en: "Advanced QML Deployment" },
      ],
    }
  ];

  // سىرتتىن مەلۇمات كەلسە ماسلاشتۇرۇش، بولمىسا ئۆلچەملىكنى ئىشلىتىش
  const certificates = data && data.length > 0 ? data.map((c, idx) => ({
    ...defaultCerts[idx] || defaultCerts[defaultCerts.length - 1],
    ...c,
    titleUg: c.title,
    titleEn: idx === 0 ? "Quantum Foundations Certified Engineer" : "Advanced Quantum AI & Machine Learning Specialist",
    issuerUg: c.issuer,
    issuerEn: idx === 0 ? "Uyghur Quantum AI Center" : "Uyghur Quantum AI Lab",
    isUnlocked: idx === 0 ? isEligible : false
  })) : defaultCerts;

  // نۆۋەتتە تاللانغان گۇۋاھنامىنى تېپىش
  const currentCert = certificates.find(c => c.id === selectedCertId) || certificates[0];

  return (
    <div className="w-full max-w-5xl mx-auto p-4 md:p-8 font-['UKIJ_Tuz','Microsoft_Uighur',sans-serif]">

      {/* ─── يۇقىرى تەرەپتىكى كونترول ستونى ─── */}
      <div className="flex flex-col md:flex-row items-center justify-between gap-4 mb-8 bg-white dark:bg-slate-900 p-4 rounded-2xl border border-slate-100 dark:border-slate-800 shadow-sm" dir="rtl">
        {/* گۇۋاھنامە تاللىغۇچ تىزىملىك */}
        <div className="flex flex-wrap gap-2">
          {certificates.map((cert) => (
            <button
              key={cert.id}
              onClick={() => setSelectedCertId(cert.id)}
              className={`px-4 py-2 text-sm font-bold rounded-xl transition flex items-center gap-2 border ${
                selectedCertId === cert.id
                  ? 'bg-indigo-600 text-white border-indigo-600 shadow-md shadow-indigo-600/10'
                  : 'bg-slate-50 hover:bg-slate-100 text-slate-700 border-slate-200 dark:bg-slate-800 dark:text-slate-300 dark:border-slate-700'
                }`}
            >
              {cert.isUnlocked ? <ShieldCheck className="w-4 h-4 text-emerald-400" /> : <Lock className="w-4 h-4 text-slate-400" />}
              <span>{cert.titleUg || cert.title}</span>
            </button>
          ))}
        </div>

        {/* تىل ئالماشتۇرۇش كۇنۇپكىسى */}
        <div className="flex items-center gap-2 bg-slate-100 dark:bg-slate-800 p-1.5 rounded-xl border border-slate-200 dark:border-slate-700">
          <button
            onClick={() => setLang('ug')}
            className={`px-4 py-1.5 rounded-lg text-xs font-black transition-all ${lang === 'ug' ? 'bg-white dark:bg-slate-900 text-indigo-600 shadow-sm' : 'text-slate-500'}`}
          >
            ئۇيغۇرچە (قۆشۇمچە EN)
          </button>
          <button
            onClick={() => setLang('en')}
            className={`px-4 py-1.5 rounded-lg text-xs font-bold font-sans transition-all ${lang === 'en' ? 'bg-white dark:bg-slate-900 text-indigo-600 shadow-sm' : 'text-slate-500'}`}
          >
            English Only
          </button>
        </div>
      </div>

      {/* ─── گۇۋاھنامە كۆرسىتىش مەيدانى ─── */}
      <div className="flex justify-center">
        {currentCert.isUnlocked ? (
          /* 🏆 گۇۋاھنامە ئوچۇق ھالەتتىكى ئالىي گرافىك لايىھە */
          <motion.div
            initial={{ opacity: 0, scale: 0.96 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{ duration: 0.4, ease: "easeOut" }}
            className="relative w-full max-w-4xl bg-stone-50 text-stone-900 overflow-hidden select-none
                       rounded-[1.75rem] shadow-2xl
                       p-[3px] bg-gradient-to-br from-amber-300 via-amber-500 to-amber-700"
          >
            {/* ئىچكى رامكا — قاتلانغان «گۆھەر رامكا» ئۇسلۇبى */}
            <div className="relative rounded-[1.6rem] bg-stone-50 border border-amber-200/70 p-8 md:p-14
                            bg-[radial-gradient(#e7e5e4_1px,transparent_1px)] [background-size:18px_18px]">

              {/* بۇلۇڭ بېزەكلىرى */}
              <div className="absolute top-3 left-3 w-16 h-16 border-t-2 border-l-2 border-amber-400/50 rounded-tl-xl pointer-events-none" />
              <div className="absolute top-3 right-3 w-16 h-16 border-t-2 border-r-2 border-amber-400/50 rounded-tr-xl pointer-events-none" />
              <div className="absolute bottom-3 left-3 w-16 h-16 border-b-2 border-l-2 border-amber-400/50 rounded-bl-xl pointer-events-none" />
              <div className="absolute bottom-3 right-3 w-16 h-16 border-b-2 border-r-2 border-amber-400/50 rounded-br-xl pointer-events-none" />

              {/* كۆرۈنمە سۇ بەلگىسى */}
              <div className="absolute inset-0 flex items-center justify-center opacity-[0.04] pointer-events-none">
                <QuantumMark size={420} />
              </div>

              {/* گۇۋاھنامە باش قىسمى */}
              <div className="relative text-center mb-6">
                <div className="mx-auto w-20 h-20 mb-3 flex items-center justify-center">
                  <QuantumMark size={80} />
                </div>

                {lang === 'ug' ? (
                  <>
                    <p className="text-xs font-sans tracking-[0.25em] text-amber-600 font-bold uppercase">Uyghur Quantum AI Academy</p>
                    <h1 className="text-3xl md:text-5xl font-black text-indigo-950 tracking-wide mt-1">شەرەپ گۇۋاھنامىسى</h1>
                    <p className="text-[11px] font-sans tracking-widest text-stone-400 font-bold uppercase mt-1">Certificate of Honor &nbsp;·&nbsp; Official Credential</p>
                  </>
                ) : (
                  <>
                    <p className="text-xs font-sans tracking-[0.25em] text-amber-600 font-bold uppercase">Uyghur Quantum AI Academy</p>
                    <h1 className="text-3xl md:text-4xl font-serif font-bold text-indigo-950 uppercase tracking-wider mt-1">Certificate of Excellence</h1>
                    <p className="text-[11px] font-sans tracking-widest text-stone-400 font-medium uppercase mt-1">Quantum AI Elite Program</p>
                  </>
                )}
              </div>

              {/* رەسمىي گۇۋاھنامە نومۇرى ۋە ئۈنۋان قۇرى */}
              <div className="relative flex flex-wrap items-center justify-center gap-x-8 gap-y-1 text-[11px] font-mono text-stone-400 tracking-wider mb-8 border-y border-stone-200/70 py-2">
                <span>{lang === 'ug' ? 'گۇۋاھنامە نومۇرى' : 'CERTIFICATE NO.'}: <b className="text-stone-600 font-bold">{currentCert.certNo}</b></span>
                <span>{lang === 'ug' ? 'بېرىلگەن چېسلا' : 'ISSUED'}: <b className="text-stone-600 font-bold">{lang === 'ug' ? currentCert.issueDateUg : currentCert.issueDateEn}</b></span>
                <span>{lang === 'ug' ? 'دەلىللەش كودى' : 'VERIFY ID'}: <b className="text-stone-600 font-bold">{currentCert.verifyCode}</b></span>
              </div>

              {/* مەزمۇن قىسمى */}
              <div className="relative text-center my-8 space-y-6">
                {lang === 'ug' ? (
                  <div className="space-y-4" dir="rtl">
                    <p className="text-lg md:text-xl text-stone-600 italic">
                      مەزكۇر شەرەپ گۇۋاھنامىسى سۇپىمىزنىڭ كۋانت ھېسابلاش سىناقلىرىدىن تولۇق مۇۋەپپەقىيەتلىك ئۆتكەن ئوقۇغۇچى:
                    </p>
                    <h2 className="text-3xl md:text-5xl font-black text-indigo-950 my-4 underline underline-offset-8 decoration-amber-400 decoration-4">
                      نەمۇنىلىك ئۆگەنچى
                    </h2>
                    <p className="text-lg md:text-xl text-stone-600">گە بېرىلدى.</p>

                    <div className="pt-2">
                      <h3 className="text-xl md:text-2xl font-black text-slate-800 max-w-2xl mx-auto leading-snug">
                        {currentCert.titleUg}
                      </h3>
                      <p className="text-xs font-sans font-semibold text-stone-400 mt-1 italic tracking-wide" dir="ltr">
                        Has successfully conferred the professional title of: <br/>
                        <span className="text-stone-600 font-bold text-sm not-italic">{currentCert.titleEn}</span>
                      </p>
                    </div>
                  </div>
                ) : (
                  <div className="space-y-4 font-serif text-center" dir="ltr">
                    <p className="text-base md:text-lg text-stone-500 italic">This is to officially certify that the student</p>
                    <h2 className="text-3xl md:text-4xl font-bold text-indigo-950 font-sans my-3 tracking-wide">
                      HONORABLE STUDENT
                    </h2>
                    <p className="text-base md:text-lg text-stone-500 italic">has successfully fulfilled all requirements and mastered the curriculum of</p>
                    <h3 className="text-xl md:text-2xl font-bold font-sans text-slate-800 max-w-2xl mx-auto">
                      {currentCert.titleEn}
                    </h3>
                  </div>
                )}
              </div>

              {/* چۈشەندۈرۈش تېكىستى */}
              <div className="relative max-w-xl mx-auto text-center border-t border-b border-stone-200/80 py-4 my-6">
                {lang === 'ug' ? (
                  <>
                    <p className="text-sm text-stone-600 leading-relaxed">
                      بۇ ئوقۇغۇچى كۋانت دەرۋازىلىرى، كۋانت ئۈستىمۇ-ئۈستى چۈشۈش ھالىتى (Superposition)، كۋانت چىرمىشىۋېلىشى (Entanglement) ۋە كۋانت سۈنئىي ئەقىل ئالگورىزىملىرىنى كۆد بىلەن لايىھەلەش ئىقتىدارىنى تولۇق نامايان قىلدى.
                    </p>
                    <p className="text-[11px] font-sans text-stone-400 mt-2 italic leading-none" dir="ltr">
                      Demonstrated expert proficiencies in Quantum Circuits, Universal Gates, Entanglement, and QML simulations.
                    </p>
                  </>
                ) : (
                  <p className="text-xs md:text-sm text-stone-500 font-sans leading-relaxed" dir="ltr">
                    The bearer has thoroughly demonstrated professional core competencies in programming multi-qubit systems, deploying Quantum Gates, managing Decoherence, and implementing advanced Quantum Machine Learning (QML) models.
                  </p>
                )}
              </div>

              {/* ئۆگەنگەن مەزمۇنلار — 4 ئاساسلىق ئىقتىدار كارتىسى */}
              <div className="relative grid grid-cols-2 md:grid-cols-4 gap-3 max-w-2xl mx-auto mb-10">
                {currentCert.competencies?.map((comp, i) => {
                  const Icon = ICONS[comp.icon] || Atom;
                  return (
                    <div key={i} className="flex flex-col items-center text-center gap-1.5 bg-white/60 border border-amber-100 rounded-xl px-2 py-3">
                      <Icon className="w-5 h-5 text-amber-600" />
                      <span className="text-[11px] font-black text-slate-700 leading-tight" dir={lang === 'ug' ? 'rtl' : 'ltr'}>
                        {lang === 'ug' ? comp.ug : comp.en}
                      </span>
                    </div>
                  );
                })}
              </div>

              {/* ─── ئاستى تەرەپتىكى رەسمىي ئىمزا ۋە كۋانت تامغىسى ─── */}
              <div className="relative mt-4 flex flex-row items-center justify-between px-2 md:px-10">
                {/* ئىمزا ستونى */}
                <div className="text-center w-48 text-right" dir={lang === 'ug' ? 'rtl' : 'ltr'}>
                  <div className="font-sans italic text-indigo-950 text-lg font-bold select-none border-b border-stone-400 pb-1 px-2 tracking-wide font-serif">
                    K. Abuduryim
                  </div>
                  <p className="text-xs font-black text-stone-700 mt-1">قاۋۇلجان ئابدۇرىيىم</p>
                  <p className="text-[10px] font-sans text-stone-400 font-medium leading-none">KawulJan Abuduryim<br/>Founder &amp; Director, UQAI</p>
                </div>

                {/* رەسمىي كۋانت تامغىسى */}
                <div className="relative flex items-center justify-center shrink-0">
                  <motion.div
                    animate={{ rotate: 360 }}
                    transition={{ duration: 30, repeat: Infinity, ease: "linear" }}
                    className="w-24 h-24 border border-dashed border-amber-500/40 rounded-full absolute"
                  />
                  <div className="w-20 h-20 bg-gradient-to-br from-amber-400 via-amber-500 to-amber-700 text-white rounded-full shadow-lg shadow-amber-500/30 flex flex-col items-center justify-center gap-0.5 border-2 border-white z-10">
                    <QuantumMark size={28} className="brightness-0 invert" />
                    <span className="text-[8px] font-black uppercase tracking-tighter leading-none">UQAI · OFFICIAL SEAL</span>
                  </div>
                </div>
              </div>

            </div>
          </motion.div>
        ) : (
          /* 🔒 گۇۋاھنامە قۇلۇپلانغان ھالەتتىكى كۆرۈنۈش */
          <div className="w-full max-w-2xl bg-white dark:bg-slate-900 p-10 rounded-3xl border border-dashed border-slate-200 dark:border-slate-800 text-center shadow-inner">
            <div className="w-16 h-16 bg-rose-50 dark:bg-rose-950/40 text-rose-500 dark:text-rose-400 rounded-2xl flex items-center justify-center mx-auto mb-4 border border-rose-100 dark:border-rose-900/30">
              <Lock className="w-7 h-7" />
            </div>
            <h2 className="text-xl font-black text-slate-800 dark:text-white">🔒 {currentCert.titleUg} قۇلۇپلاقلىق</h2>
            <p className="text-slate-500 dark:text-slate-400 mt-2 text-sm max-w-md mx-auto leading-relaxed" dir="rtl">
              مەزكۇر ئاكادېمىك شەرەپ گۇۋاھنامىسىگە ئېرىشىش ئۈچۈن، سۇپىدىكى زۆرۈر دەرسلەرنى تاماملاپ، بىلىم سىناش مەشىقلىرىگە تولۇق توغرا جاۋاب بېرىڭ.
            </p>
            <div className="mt-4 flex justify-center gap-6 text-xs font-mono text-slate-400 border-t border-slate-100 dark:border-slate-800 pt-4">
              <span>تەلەپ دەرس: {currentCert.reqLessons || 3}</span>
              <span>تەلەپ مەشىق: {currentCert.reqExercises || 2}</span>
            </div>
          </div>
        )}
      </div>

    </div>
  );
}