// src/components/quantum/QuantumGate.jsx
import React from 'react';

export default function QuantumGate({ type, label, color }) {
  const handleDragStart = (e) => {
    e.dataTransfer.setData("gateType", type);
  };

  return (
    <div
      draggable
      onDragStart={handleDragStart}
      className={`w-12 h-12 flex items-center justify-center rounded-xl font-bold text-white shadow-md cursor-grab active:cursor-grabbing transition transform hover:scale-105 select-none ${color}`}
      title={`${label} Gate`}
    >
      {type === 'CNOT' ? '●' : type === 'Measure' ? 'M' : type}
    </div>
  );
}