import React from "react";
import { useLocation, useNavigate } from "react-router-dom";

const LectureDetail = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const course = location.state; // ئالدىنقى بەتتىن كەلگەن تولۇق جەيسان ئۇچۇرى

  // ئەگەر يۆتكىلىشتە مەسىلە چىقىپ ئۇچۇر كەلمىگەن بولسا ئاگاھلاندۇرۇش چىقىرىش
  if (!course) {
    return (
      <div className="min-h-screen flex flex-col justify-center items-center bg-slate-50 dark:bg-slate-950 text-slate-800 dark:text-slate-200" dir="rtl">
        <p className="text-xl font-bold mb-4">⚠️ لىكسىيە ئۇچۇرلىرى يۈكلەنمىدى.</p>
        <button onClick={() => navigate(-1)} className="px-5 py-2 bg-blue-600 text-white rounded-xl">ئارقىغا قايتىش</button>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 py-10 px-4 md:px-8 transition-colors duration-300" dir="rtl">
      <div className="max-w-5xl mx-auto space-y-8">
        
        {/* ئارقىغا قايتىش كۇنۇپكىسى */}
        <button 
          onClick={() => navigate(-1)} 
          className="flex items-center gap-2 text-sm font-bold text-slate-600 dark:text-slate-400 hover:text-blue-600 dark:hover:text-blue-400 transition"
        >
          <span>⬅️</span> ئاساسىي بەتكە قايتىش
        </button>

        {/* 1. ئۈستۈنكى قىسىم (Banner & تېز ئۇچۇرلار) */}
        <div className="bg-white dark:bg-slate-900 rounded-3xl p-6 md:p-8 shadow-xl border border-slate-100 dark:border-slate-800 grid grid-cols-1 md:grid-cols-3 gap-8 items-center">
          
          {/* لىكسىيە مۇقاۋىسى */}
          <div className="md:col-span-1 flex justify-center">
            <img 
              src={`${process.env.PUBLIC_URL}/${course.image}`} 
              alt={course.title}
              className="w-full max-w-[260px] h-auto object-cover rounded-2xl shadow-md border-4 border-slate-50 dark:border-slate-800 transform hover:scale-[1.02] transition duration-300"
              onError={(e) => { e.target.src = `${process.env.PUBLIC_URL}/images/image05.png`; }}
            />
          </div>

          {/* لىكسىيە يادرولۇق ئۇچۇرلىرى */}
          <div className="md:col-span-2 space-y-4 text-right">
            <div className="flex flex-wrap gap-2">
              <span className="bg-blue-100 dark:bg-blue-950 text-blue-700 dark:text-blue-400 text-xs font-bold px-3 py-1 rounded-full">{course.category}</span>
              <span className="bg-emerald-100 dark:bg-emerald-950 text-emerald-700 dark:text-emerald-400 text-xs font-bold px-3 py-1 rounded-full">{course.level}</span>
              <span className="bg-purple-100 dark:bg-purple-950 text-purple-700 dark:text-purple-400 text-xs font-bold px-3 py-1 rounded-full">{course.price}</span>
            </div>
            
            <h1 className="text-2xl md:text-3xl font-black text-slate-800 dark:text-slate-100 leading-tight">
              {course.title}
            </h1>

            <p className="text-sm text-slate-500 dark:text-slate-400">
              👤 لىكسىيە سۆزلىگۈچى: <span className="font-bold text-slate-700 dark:text-slate-200">{course.speaker}</span>
            </p>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 pt-2 text-xs text-slate-600 dark:text-slate-400 border-t border-slate-100 dark:border-slate-800">
              <div>📅 ۋاقتى: <span className="font-medium text-slate-800 dark:text-slate-200">{course.date}</span></div>
              <div>⏱️ داۋاملىشىشى: <span className="font-medium text-slate-800 dark:text-slate-200">{course.duration}</span></div>
              <div>🌐 تىل: <span className="font-medium text-slate-800 dark:text-slate-200">{course.language}</span></div>
              <div>🔑 ئالدىنقى شەرت: <span className="font-medium text-slate-800 dark:text-slate-200 text-rose-600 dark:text-rose-400">{course.prerequisites}</span></div>
            </div>
          </div>
        </div>

        {/* 2. ئاساسىي مەزمۇن قىسمى (داۋامى) */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          
          {/* سول تەرەپ: تەپسىلاتلار ۋە ئۆگىنىش نۇقتىلىرى (2 ئۈلۈش) */}
          <div className="lg:col-span-2 space-y-6">
            
            {/* تەپسىلىي چۈشەندۈرۈلۈشى */}
            <div className="bg-white dark:bg-slate-900 p-6 md:p-8 rounded-3xl shadow-md border border-slate-100 dark:border-slate-800 whitespace-pre-line text-slate-700 dark:text-slate-300 text-base leading-relaxed">
              <h3 className="text-lg font-bold text-slate-800 dark:text-slate-100 mb-4 flex items-center gap-2 border-b pb-2 border-slate-100 dark:border-slate-800">
                📄 لىكسىيە ھەققىدە تەپسىلىي چۈشەندۈرۈش
              </h3>
              {course.detailedDescription}
            </div>

            {/* نېمىلەرنى ئۆگىنىسىز (What You Learn) */}
            {course.whatYouLearn && course.whatYouLearn.length > 0 && (
              <div className="bg-white dark:bg-slate-900 p-6 md:p-8 rounded-3xl shadow-md border border-slate-100 dark:border-slate-800">
                <h3 className="text-lg font-bold text-slate-800 dark:text-slate-100 mb-4 flex items-center gap-2 border-b pb-2 border-slate-100 dark:border-slate-800">
                  ✅ بۇ لىكسىيەدىن نېمىلەرگە ئېرىشىسىز؟
                </h3>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  {course.whatYouLearn.map((item, idx) => (
                    <div key={idx} className="flex items-start gap-2 text-sm text-slate-600 dark:text-slate-300">
                      <span className="text-emerald-500 font-bold">✓</span>
                      <span>{item}</span>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>

          {/* ئوڭ تەرەپ: ياردەمچى تاختا، ئۇلىنىشلار ۋە نىشان كىشىلەر (1 ئۈلۈش) */}
          <div className="lg:col-span-1 space-y-6">
            
            {/* نەق مەيدان ۋە ئالاقە ئۇلىنىشلىرى */}
            <div className="bg-white dark:bg-slate-900 p-6 rounded-3xl shadow-md border border-slate-100 dark:border-slate-800 space-y-4">
              <h3 className="text-md font-bold text-slate-800 dark:text-slate-100 border-b pb-2 border-slate-100 dark:border-slate-800">
                🔗 لىكسىيە ئۇلىنىشلىرى
              </h3>
              
              <div className="space-y-2.5" dir="ltr">
                {course.zoomLink && (
                  <a href={course.zoomLink} target="_blank" rel="noreferrer" className="w-full flex items-center justify-between p-3 bg-blue-50 hover:bg-blue-100 dark:bg-blue-950/40 dark:hover:bg-blue-950 rounded-xl text-blue-700 dark:text-blue-400 font-medium text-xs transition">
                    <span className="font-bold text-right text-sm">🚪 Zoom غا كىرىش</span>
                    <span className="text-[11px] opacity-70">نەق مەيدان</span>
                  </a>
                )}
                {course.link && (
                  <a href={course.link} target="_blank" rel="noreferrer" className="w-full flex items-center justify-between p-3 bg-rose-50 hover:bg-rose-100 dark:bg-rose-950/40 dark:hover:bg-rose-950 rounded-xl text-rose-700 dark:text-rose-400 font-medium text-xs transition">
                    <span className="font-bold text-right text-sm">📺 YouTube لىنكى</span>
                    <span className="text-[11px] opacity-70">ۋىدېئو كۆرۈش</span>
                  </a>
                )}
                {course.otherLink && (
                  <a href={course.otherLink} target="_blank" rel="noreferrer" className="w-full flex items-center justify-between p-3 bg-slate-50 hover:bg-slate-100 dark:bg-slate-800 dark:hover:bg-slate-700 rounded-xl text-slate-700 dark:text-slate-300 font-medium text-xs transition">
                    <span className="font-bold text-right text-sm">🔗 قوشۇمچە ئۇلىنىش</span>
                    <span className="text-[11px] opacity-70">ماتېرىيال</span>
                  </a>
                )}
              </div>
            </div>

            {/* كىملەرگە مۇناسىپ (Target Audience) */}
            {course.targetAudience && course.targetAudience.length > 0 && (
              <div className="bg-white dark:bg-slate-900 p-6 rounded-3xl shadow-md border border-slate-100 dark:border-slate-800">
                <h3 className="text-md font-bold text-slate-800 dark:text-slate-100 mb-3 border-b pb-2 border-slate-100 dark:border-slate-800">
                  👥 كىملەرگە مۇناسىپ؟
                </h3>
                <ul className="space-y-2 text-xs text-slate-600 dark:text-slate-400 list-disc list-inside">
                  {course.targetAudience.map((audience, idx) => (
                    <li key={idx} className="leading-relaxed">{audience}</li>
                  ))}
                </ul>
              </div>
            )}

            {/* ئالاقىدار شىئار / ھېكمەتلىك سۆز (Quote) */}
            {course.quote && (
              <div className="bg-gradient-to-br from-blue-600 to-indigo-700 p-5 rounded-3xl text-white shadow-lg text-center relative overflow-hidden group">
                <div className="absolute -right-4 -bottom-4 text-white/10 text-7xl font-serif pointer-events-none group-hover:scale-110 transition duration-500">“</div>
                <p className="italic text-sm font-medium leading-relaxed relative z-10">
                  "{course.quote}"
                </p>
              </div>
            )}

          </div>
        </div>

      </div>
    </div>
  );
};

export default LectureDetail;