import React, { useContext, useRef, useState } from 'react';
import { ArrowLeftRight, RotateCcw, Mic, Volume2, Languages, Cpu, Globe, Check, Copy } from 'lucide-react';
import { useTheme } from '../context/ThemeContext';

const TranslateTab = ({ 
  inputText, 
  setInputText, 
  outputText, 
  setOutputText, 
  loading, 
  sourceLang, 
  setSourceLang, 
  targetLang, 
  setTargetLang, 
  handleTranslate // ئەگەر سىرتتىن كەلگەن فۇنكسىيە بولسا ئىشلىتىلىدۇ
}) => {
  // تېما كۇنتېكىستىنى بىخەتەر ئوقۇش
  let darkMode = false;
  try {
    const themeContext = useTheme();
    darkMode = themeContext?.darkMode;
  } catch (e) {
    darkMode = false;
  }

  const [isListening, setIsListening] = useState(false);
  const [copied, setCopied] = useState(false);
  
  // يېڭىدىن قوشۇلغان تەرجىمە ماتورى تاللاش ھالىتى (لوكال مودېل ياكى API)
  const [engine, setEngine] = useState('local_llm'); // 'local_llm' ياكى 'cloud_api'
  
  const recognitionRef = useRef(null);

  // 7 خىل تىل تاللانمىسى (ئۇيغۇر تىلى بىرىنچى ئورۇندا)
  const languageOptions = [
    { value: 'ug', label: 'ئۇيغۇرچە', isRtl: true },
    { value: 'en', label: 'English', isRtl: false },
    { value: 'zh', label: '中文 (简体)', isRtl: false },
    { value: 'tr', label: 'Türkçe', isRtl: false },
    { value: 'ar', label: 'العربية', isRtl: true },
    { value: 'ru', label: 'Русский', isRtl: false },
    { value: 'ja', label: '日本語', isRtl: false }
  ];

  const swapLanguages = () => {
    setSourceLang(targetLang);
    setTargetLang(sourceLang);
    setInputText(outputText);
    setOutputText(inputText);
  };

  const clearAll = () => {
    setInputText('');
    setOutputText('');
  };

  const handleCopy = async () => {
    if (!outputText) return;
    try {
      await navigator.clipboard.writeText(outputText);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (err) {
      console.error('كۆچۈرۈش مەغلۇپ بولدى:', err);
    }
  };

  // ئاۋاز كىرگۈزۈش (STT)
  const startListening = () => {
    if (!('SpeechRecognition' in window) && !('webkitSpeechRecognition' in window)) {
      alert(sourceLang === 'ug' ? 'براۋزېرىڭىز ئاۋاز كىرگۈزۈشنى قوللىمايدۇ.' : 'Speech recognition is not supported.');
      return;
    }

    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    recognitionRef.current = new SpeechRecognition();
    recognitionRef.current.continuous = false;
    recognitionRef.current.interimResults = false;
    
    // تىل كودىنى بېكىتىش
    const langMap = { ug: 'ug', zh: 'zh-CN', en: 'en-US', tr: 'tr-TR', ar: 'ar-SA', ru: 'ru-RU', ja: 'ja-JP' };
    recognitionRef.current.lang = langMap[sourceLang] || 'en-US';

    recognitionRef.current.onresult = (event) => {
      const transcript = event.results[0][0].transcript;
      setInputText(transcript);
    };

    recognitionRef.current.onerror = () => setIsListening(false);
    recognitionRef.current.onend = () => setIsListening(false);
    recognitionRef.current.start();
    setIsListening(true);
  };

  const stopListening = () => {
    if (recognitionRef.current) {
      recognitionRef.current.stop();
      setIsListening(false);
    }
  };

  // ئاۋاز بېرىش (TTS)
  const speakText = (text, lang) => {
    if (!text) return;
    const utterance = new SpeechSynthesisUtterance(text);
    const langMap = { ug: 'ug', zh: 'zh-CN', en: 'en-US', tr: 'tr-TR', ar: 'ar-SA', ru: 'ru-RU', ja: 'ja-JP' };
    utterance.lang = langMap[lang] || 'en-US';
    utterance.rate = 0.95;
    window.speechSynthesis.speak(utterance);
  };

  // تەرجىمە ئىجرا قىلىش بېجىرگۈچىسى
  const onTranslateClick = () => {
    if (!inputText.trim()) return;
    
    // ئەگەر سىرتتىن handleTranslate فۇنكسىيەسى كەلگەن بولسا، ئۇنىڭغا مۆلچەرلەنگەن موتورنى قوشۇپ بېرىمىز
    if (handleTranslate) {
      handleTranslate({
        text: inputText,
        source: sourceLang,
        target: targetLang,
        engine: engine // 'local_llm' ياكى 'cloud_api' نى سىرتتىكى API غا يوللايدۇ
      });
    }
  };

  const isSourceRtl = languageOptions.find(l => l.value === sourceLang)?.isRtl;
  const isTargetRtl = languageOptions.find(l => l.value === targetLang)?.isRtl;

  return (
    <div 
      className={`w-full max-w-5xl mx-auto rounded-2xl shadow-2xl p-6 md:p-8 border ${
        darkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-100'
      } transition-all duration-300`} 
      dir="rtl"
    >
      {/* 1. باشلىق قىسمى */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6 border-b pb-4 border-slate-100 dark:border-slate-800">
        <div className="flex items-center gap-3">
          <div className={`p-3 rounded-xl ${darkMode ? 'bg-teal-950/40 text-teal-400' : 'bg-teal-50 text-teal-600'}`}>
            <Languages className="w-6 h-6 animate-pulse" />
          </div>
          <div>
            <h2 className={`text-2xl font-black font-uyghur tracking-wide ${darkMode ? 'text-white' : 'text-slate-800'}`}>
              قۇتادغۇ ئەقلىي تەرجىمان
            </h2>
            <p className="text-xs text-gray-400 dark:text-gray-500 font-mono mt-0.5">KelBiL Quantum AI Translation Engine v2.0</p>
          </div>
        </div>

        {/* تەرجىمە موتورىنى ئالماشتۇرۇش (يەرلىك مودېل / تور API) */}
        <div className="flex bg-slate-100 dark:bg-slate-800 p-1 rounded-xl border border-slate-200/50 dark:border-slate-700/50 self-start sm:self-center">
          <button
            onClick={() => setEngine('local_llm')}
            className={`flex items-center gap-1.5 px-4 py-2 rounded-lg text-sm font-bold font-uyghur transition-all ${
              engine === 'local_llm'
                ? 'bg-gradient-to-r from-teal-600 to-teal-500 text-white shadow-sm'
                : 'text-slate-600 dark:text-slate-400 hover:text-slate-800 dark:hover:text-slate-200'
            }`}
          >
            <Cpu className="w-4 h-4" />
            <span>لوكال چوڭ مودېل (LLM)</span>
          </button>
          <button
            onClick={() => setEngine('cloud_api')}
            className={`flex items-center gap-1.5 px-4 py-2 rounded-lg text-sm font-bold font-uyghur transition-all ${
              engine === 'cloud_api'
                ? 'bg-gradient-to-r from-indigo-600 to-indigo-500 text-white shadow-sm'
                : 'text-slate-600 dark:text-slate-400 hover:text-slate-800 dark:hover:text-slate-200'
            }`}
          >
            <Globe className="w-4 h-4" />
            <span>بۇلۇت API تەرجىمىسى</span>
          </button>
        </div>
      </div>

      {/* 2. تىل تاللاش كۆزنىكى */}
      <div className="flex flex-col md:flex-row md:items-center gap-4 mb-6">
        {/* مەنبە تىل */}
        <div className="flex-1">
          <label className={`block text-base font-bold mb-2 font-uyghur ${darkMode ? 'text-slate-300' : 'text-slate-600'}`}>
            مەنبە تىل (Source)
          </label>
          <select
            value={sourceLang}
            onChange={(e) => setSourceLang(e.target.value)}
            className={`w-full p-3.5 font-bold font-uyghur rounded-xl border focus:outline-none focus:ring-2 focus:ring-teal-500 shadow-sm cursor-pointer text-lg ${
              darkMode ? 'bg-slate-950 border-slate-700 text-white' : 'bg-slate-50 border-slate-200 text-slate-800'
            }`}
          >
            {languageOptions.map(opt => (
              <option key={opt.value} value={opt.value}>{opt.label}</option>
            ))}
          </select>
        </div>

        {/* ئالماشتۇرۇش كۇنۇپكىسى */}
        <div className="flex justify-center items-center pt-2 md:pt-8">
          <button
            onClick={swapLanguages}
            className={`p-3.5 rounded-xl hover:scale-110 active:scale-95 border transition-all shadow-md cursor-pointer ${
              darkMode 
                ? 'bg-slate-800 hover:bg-slate-700 border-slate-700 text-teal-400' 
                : 'bg-white hover:bg-slate-50 border-slate-200 text-teal-600'
            }`}
            title="تىللارنى ئالماشتۇرۇش"
          >
            <ArrowLeftRight className="w-5 h-5 max-md:rotate-90" />
          </button>
        </div>

        {/* نىشان تىل */}
        <div className="flex-1">
          <label className={`block text-base font-bold mb-2 font-uyghur ${darkMode ? 'text-slate-300' : 'text-slate-600'}`}>
            نىشان تىل (Target)
          </label>
          <select
            value={targetLang}
            onChange={(e) => setTargetLang(e.target.value)}
            className={`w-full p-3.5 font-bold font-uyghur rounded-xl border focus:outline-none focus:ring-2 focus:ring-teal-500 shadow-sm cursor-pointer text-lg ${
              darkMode ? 'bg-slate-950 border-slate-700 text-white' : 'bg-slate-50 border-slate-200 text-slate-800'
            }`}
          >
            {languageOptions.map(opt => (
              <option key={opt.value} value={opt.value}>{opt.label}</option>
            ))}
          </select>
        </div>
      </div>

      {/* 3. كىرگۈزۈش ۋە چىقىرىش قوش كۆزنەك تۈزۈلۈشى (رېسپانسبىل پىورفېسسىيونال يۈز) */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-5 mb-6">
        
        {/* سول ياكى ئوڭ كىرگۈزۈش تاختىسى */}
        <div className="flex flex-col border border-slate-200 dark:border-slate-800 rounded-2xl p-4 bg-slate-50/50 dark:bg-slate-950/20">
          <div className="flex justify-between items-center mb-2.5">
            <span className={`text-base font-bold font-uyghur ${darkMode ? 'text-slate-300' : 'text-slate-600'}`}>
              مەزمۇن كىرگۈزۈش
            </span>
            <div className="flex gap-1.5">
              <button
                onClick={isListening ? stopListening : startListening}
                className={`p-2 rounded-lg transition-all cursor-pointer ${
                  isListening ? 'bg-rose-500 text-white animate-pulse shadow-md' : 'bg-slate-200 dark:bg-slate-800 text-slate-500 hover:bg-slate-300'
                }`}
                title="ئاۋازلىق كىرگۈزۈش"
              >
                <Mic className="w-4 h-4" />
              </button>
              <button
                onClick={clearAll}
                className="p-2 rounded-lg bg-slate-200 dark:bg-slate-800 text-slate-500 hover:bg-slate-300 transition-all cursor-pointer"
                title="تازىلاش"
              >
                <RotateCcw className="w-4 h-4" />
              </button>
            </div>
          </div>
          <textarea
            value={inputText}
            onChange={(e) => setInputText(e.target.value)}
            placeholder={isSourceRtl ? 'بۇ يەرگە مەزمۇن يېزىڭ ياكى چاپلاڭ...' : 'Type or paste your text here...'}
            dir={isSourceRtl ? 'rtl' : 'ltr'}
            className={`w-full min-h-[180px] p-3.5 rounded-xl border-none focus:outline-none text-xl font-uyghur resize-none bg-transparent ${
              darkMode ? 'text-white' : 'text-slate-800'
            }`}
          />
        </div>

        {/* چىقىرىش نەتىجە تاختىسى */}
        <div className="flex flex-col border border-slate-200 dark:border-slate-800 rounded-2xl p-4 bg-slate-50/50 dark:bg-slate-950/20 relative">
          <div className="flex justify-between items-center mb-2.5">
            <span className={`text-base font-bold font-uyghur ${darkMode ? 'text-slate-300' : 'text-slate-600'}`}>
              تەرجىمە نەتىجىسى
            </span>
            {outputText && (
              <div className="flex gap-1.5">
                <button
                  onClick={handleCopy}
                  className="p-2 rounded-lg bg-slate-200 dark:bg-slate-800 text-slate-500 hover:bg-slate-300 transition-all cursor-pointer"
                  title="نەتىجىنى كۆچۈرۈش"
                >
                  {copied ? <Check className="w-4 h-4 text-emerald-500" /> : <Copy className="w-4 h-4" />}
                </button>
                <button
                  onClick={() => speakText(outputText, targetLang)}
                  className="p-2 rounded-lg bg-slate-200 dark:bg-slate-800 text-slate-500 hover:bg-slate-300 transition-all cursor-pointer"
                  title="ئاۋازلىق ئوقۇش"
                >
                  <Volume2 className="w-4 h-4" />
                </button>
              </div>
            )}
          </div>
          <div 
            dir={isTargetRtl ? 'rtl' : 'ltr'}
            className={`w-full min-h-[180px] p-3.5 rounded-xl text-xl font-uyghur whitespace-pre-wrap overflow-y-auto ${
              outputText ? (darkMode ? 'text-white font-bold' : 'text-slate-900 font-bold') : 'text-slate-400 font-normal italic'
            }`}
          >
            {outputText || (isTargetRtl ? 'تەرجىمە نەتىجىسى بۇ يەردە كۆرۈنىدۇ...' : 'Translation will appear here...')}
          </div>
        </div>

      </div>

      {/* 4. تەرجىمە قىلىش ھەرىكەت كۇنۇپكىسى */}
      <button
        onClick={onTranslateClick}
        disabled={loading || !inputText.trim()}
        className={`w-full py-4.5 rounded-xl font-black font-uyghur text-xl text-white flex items-center justify-center gap-2 transition-all cursor-pointer ${
          loading || !inputText.trim()
            ? 'bg-slate-300 dark:bg-slate-800 text-slate-500 cursor-not-allowed shadow-none'
            : engine === 'local_llm'
              ? 'bg-gradient-to-r from-teal-600 via-teal-500 to-cyan-600 hover:from-teal-500 hover:to-cyan-500 shadow-lg shadow-teal-500/20 hover:-translate-y-0.5'
              : 'bg-gradient-to-r from-indigo-600 via-purple-600 to-blue-600 hover:from-indigo-500 hover:to-blue-500 shadow-lg shadow-indigo-500/20 hover:-translate-y-0.5'
        }`}
      >
        {loading ? (
          <>
            <div className="w-6 h-6 border-3 border-white border-t-transparent rounded-full animate-spin"></div>
            <span>{engine === 'local_llm' ? 'لوكال چوڭ مودېل تەرجىمە قىلىۋاتىدۇ...' : 'بۇلۇت API تەرجىمە قىلىۋاتىدۇ...'}</span>
          </>
        ) : (
          <>
            <Languages className="w-5 h-5" />
            <span>{engine === 'local_llm' ? 'لوكال مودېل (LLM) بىلەن تەرجىمە قىلىش' : 'بۇلۇت API سىستېمىسىدا تەرجىمە قىلىش'}</span>
          </>
        )}
      </button>

    </div>
  );
};

export default TranslateTab;