import { useState } from "react";

export default function AddClassForm({ onAdd, onCancel }) {
  const [formData, setFormData] = useState({
    title: "",
    platform: "Zoom",
    time: "",
    link: ""
  });

  // خاتالىق ئۇچۇرلىرىنى ساقلاش ھالىتى
  const [errors, setErrors] = useState({});

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
    
    // ئىشلەتكۈچى يېزىشقا باشلىغاندا خاتالىق ئاگاھلاندۇرۇشىنى ئۆچۈرۈش
    if (errors[name]) {
      setErrors({ ...errors, [name]: "" });
    }
  };

  // جەدۋەلنى تەكشۈرۈش فۇنكسىيەسى
  const validateForm = () => {
    let tempErrors = {};
    if (!formData.title.trim()) tempErrors.title = "دەرس نامىنى كىرگۈزۈڭ";
    if (!formData.time) tempErrors.time = "ۋاقىتنى تاللاڭ";
    
    // URL نى يىنىك تەكشۈرۈش
    if (!formData.link.trim()) {
      tempErrors.link = "دەرس ئۇلىنىشىنى كىرگۈزۈڭ";
    } else if (!/^https?:\/\/.+/i.test(formData.link)) {
      tempErrors.link = "توغرا بولغان ئۇلىنىش ئادرېسى كىرگۈزۈڭ (https://...)";
    }

    setErrors(tempErrors);
    return Object.keys(tempErrors).length === 0;
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    
    if (!validateForm()) return;

    onAdd({ ...formData, id: Date.now() });
    
    // جەدۋەلنى ئەسلىگە كەلتۈرۈش
    setFormData({ title: "", platform: "Zoom", time: "", link: "" });
    setErrors({});
  };

  return (
    <form 
      onSubmit={handleSubmit} 
      className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg border border-gray-100 dark:border-gray-700 mb-8 max-w-xl mx-auto transition-all text-right"
      dir="rtl"
    >
      <h3 className="text-xl font-bold text-gray-800 dark:text-white mb-6 flex items-center gap-2 border-b pb-3 border-gray-100 dark:border-gray-700">
        <span>➕ يېڭى دەرس قوشۇش</span>
      </h3>

      {/* 1. دەرس نامى */}
      <div className="mb-4">
        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1.5">📝 دەرس نامى</label>
        <input
          type="text"
          name="title"
          placeholder="مەسىلەن: پايتون پروگراممىلاش ئاساسلىرى"
          value={formData.title}
          onChange={handleChange}
          className={`w-full px-4 py-2.5 border text-sm rounded-lg bg-gray-50 dark:bg-gray-900 dark:text-white focus:bg-white outline-none transition-all ${
            errors.title 
              ? "border-red-500 focus:ring-2 focus:ring-red-200" 
              : "border-gray-300 dark:border-gray-600 focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100 dark:focus:ring-indigo-900"
          }`}
        />
        {errors.title && <p className="text-xs text-red-500 mt-1">{errors.title}</p>}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
        {/* 2. سۇپا تاللاش */}
        <div>
          <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1.5">💻 لىكسىيە سۇپىسى</label>
          <select
            name="platform"
            value={formData.platform}
            onChange={handleChange}
            className="w-full px-4 py-2.5 border border-gray-300 dark:border-gray-600 text-sm rounded-lg bg-gray-50 dark:bg-gray-900 dark:text-white focus:bg-white outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100 dark:focus:ring-indigo-900 transition-all cursor-pointer"
          >
            <option value="Zoom">Zoom</option>
            <option value="Google Meet">Google Meet</option>
            <option value="Microsoft Teams">Microsoft Teams</option>
          </select>
        </div>

        {/* 3. دەرس ۋاقتى */}
        <div>
          <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1.5">📅 ئۆتكۈزۈلىدىغان ۋاقىت</label>
          <input
            type="datetime-local"
            name="time"
            value={formData.time}
            onChange={handleChange}
            className={`w-full px-4 py-2.5 border text-sm rounded-lg bg-gray-50 dark:bg-gray-900 dark:text-white focus:bg-white outline-none transition-all ${
              errors.time 
                ? "border-red-500 focus:ring-2 focus:ring-red-200" 
                : "border-gray-300 dark:border-gray-600 focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100 dark:focus:ring-indigo-900"
            }`}
          />
          {errors.time && <p className="text-xs text-red-500 mt-1">{errors.time}</p>}
        </div>
      </div>

      {/* 4. دەرس ئۇلىنىشى */}
      <div className="mb-6">
        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1.5">🔗 دەرس ئۇلىنىشى (Link)</label>
        <input
          type="text"
          name="link"
          placeholder="https://zoom.us/j/... ياكى يۇتۇب ئۇلىنىشى"
          value={formData.link}
          onChange={handleChange}
          className={`w-full px-4 py-2.5 border text-left text-sm rounded-lg bg-gray-50 dark:bg-gray-900 dark:text-white focus:bg-white outline-none transition-all ${
            errors.link 
              ? "border-red-500 focus:ring-2 focus:ring-red-200" 
              : "border-gray-300 dark:border-gray-600 focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100 dark:focus:ring-indigo-900"
          }`}
          dir="ltr" // تور ئادرېسى چوقۇم سولدىن ئوڭغا يېزىلىدۇ
        />
        {errors.link && <p className="text-xs text-red-500 mt-1">{errors.link}</p>}
      </div>

      {/* كۇنۇپكىلار سىستېمىسى */}
      <div className="flex gap-3 justify-start border-t pt-4 border-gray-100 dark:border-gray-700">
        <button
          type="submit"
          className="bg-indigo-600 hover:bg-indigo-700 text-white font-medium px-6 py-2.5 rounded-lg text-sm transition-all shadow-md hover:shadow-indigo-200 dark:hover:shadow-none"
        >
          جەدۋەلنى قوشۇش
        </button>
        <button
          type="button"
          onClick={onCancel}
          className="bg-gray-200 hover:bg-gray-300 dark:bg-gray-700 dark:hover:bg-gray-600 text-gray-700 dark:text-gray-200 font-medium px-6 py-2.5 rounded-lg text-sm transition-all"
        >
          ۋاز كېچىش
        </button>
      </div>
    </form>
  );
}