// src/components/quantum/QuantumCircuitBuilder.jsx
import React, { useState, useEffect } from 'react';
import QuantumToolbar from './QuantumToolbar';

export default function QuantumCircuitBuilder() {
  // دەسلەپتە 3 دانە كۇبىت بىلەن باشلايمىز (q0, q1, q2)
  const [qubitCount, setQubitCount] = useState(3);
  
  // زەنجىر قۇرۇلمىسى: 8 دانە ۋاقىت باسقۇچى (Columns)
  // ھەر بىر باسقۇچ بىر ئوبجېكت بولۇپ، كۇبىتلارنىڭ دەرۋازىسىنى ساقلايدۇ، مەسىلەن: { q0: 'H', q1: null, q2: 'X' }
  const [steps, setSteps] = useState([
    { q0: null, q1: null, q2: null },
    { q0: null, q1: null, q2: null },
    { q0: null, q1: null, q2: null },
    { q0: null, q1: null, q2: null },
    { q0: null, q1: null, q2: null },
    { q0: null, q1: null, q2: null },
    { q0: null, q1: null, q2: null },
    { q0: null, q1: null, q2: null },
  ]);

  const [textResult, setTextResult] = useState('');
  const [pythonCode, setPythonCode] = useState('');
  const [copied, setCopied] = useState(false);

  // كۇبىت سانى ئۆزگەرگەندە زەنجىر قۇرۇلمىسىنى يېڭىلاش
  useEffect(() => {
    setSteps(prevSteps => 
      prevSteps.map(step => {
        const newStep = {};
        for (let i = 0; i < qubitCount; i++) {
          const qId = `q${i}`;
          // ئەگەر كونا ئورۇندا دەرۋازا بولسا ساقلاپ قالىدۇ، بولمىسا null قىلىدۇ
          newStep[qId] = step[qId] || null;
        }
        return newStep;
      })
    );
  }, [qubitCount]);

  // يېڭى كۇبىت لىنىيىسى قوشۇش (ئەڭ كۆپ بولغاندا 8 كۇبىت)
  const addQubit = () => {
    if (qubitCount < 8) {
      setQubitCount(prev => prev + 1);
    }
  };

  // ئاخىرقى كۇبىت لىنىيىسىنى ئۆچۈرۈش (كەم دېگەندە 1 كۇبىت قېلىشى كېرەك)
  const removeQubit = () => {
    if (qubitCount > 1) {
      setQubitCount(prev => prev - 1);
    }
  };

  const handleDragOver = (e) => {
    e.preventDefault();
  };

  // دەرۋازا تاشلانغاندا قوزغىلىدۇ
  const handleDrop = (e, qubitId, stepIdx) => {
    e.preventDefault();
    const gateType = e.dataTransfer.getData("gateType");
    if (!gateType) return;

    const currentQubitIndex = parseInt(qubitId.replace('q', ''));

    setSteps(prevSteps => {
      const newSteps = [...prevSteps];
      const currentStep = { ...newSteps[stepIdx] };

      // ئەگەر CNOT ياكى SWAP تاشلانسا (ئىككى كۇبىتلىق دەرۋازا)
      if (gateType === 'CNOT' || gateType === 'SWAP') {
        // ئەگەر ئەڭ ئاستىدىكى كۇبىتقا تاشلانسا، ئۈستىدىكى كۇبىت بىلەن باغلانسۇن
        const isLastQubit = currentQubitIndex === qubitCount - 1;
        const targetQubitIndex = isLastQubit ? currentQubitIndex - 1 : currentQubitIndex + 1;
        
        const controlKey = `q${isLastQubit ? targetQubitIndex : currentQubitIndex}`;
        const targetKey = `q${isLastQubit ? currentQubitIndex : targetQubitIndex}`;

        // كونا بار بولغان دەرۋازىلارنى پاكىزلاش
        currentStep[controlKey] = gateType === 'CNOT' ? 'CNOT-CONTROL' : 'SWAP';
        currentStep[targetKey] = gateType === 'CNOT' ? 'CNOT-TARGET' : 'SWAP';

        newSteps[stepIdx] = currentStep;
      } else {
        // يەككە كۇبىت دەرۋازىلىرى (H, X, Y, Z, Measure)
        // ئەگەر تاشلانغان ئورۇندا ئىلگىرى CNOT ياكى SWAP باغلانغان بولسا، شۇ تۈۋرۈكتىكى قوشنا باغلانغۇچىنى تازىلايدۇ
        const oldGate = currentStep[qubitId];
        if (oldGate === 'CNOT-CONTROL' || oldGate === 'CNOT-TARGET' || oldGate === 'SWAP') {
          // پۈتۈن تۈۋرۈكتىكى باغلانما دەرۋازىلارنى نۆللەشتۈرۈش
          for (let i = 0; i < qubitCount; i++) {
            if (currentStep[`q${i}`] === 'CNOT-CONTROL' || currentStep[`q${i}`] === 'CNOT-TARGET' || currentStep[`q${i}`] === 'SWAP') {
              currentStep[`q${i}`] = null;
            }
          }
        }
        currentStep[qubitId] = gateType;
        newSteps[stepIdx] = currentStep;
      }
      return newSteps;
    });
  };

  // دەرۋازىنى چىكىپ ئۆچۈرۈۋېتىش
  const removeGate = (qubitId, stepIdx) => {
    setSteps(prevSteps => {
      const newSteps = [...prevSteps];
      const currentStep = { ...newSteps[stepIdx] };
      const gate = currentStep[qubitId];

      if (gate === 'CNOT-CONTROL' || gate === 'CNOT-TARGET' || gate === 'SWAP') {
        // باغلانغان قوش جفت دەرۋازىلارنىڭ ئىككىلىسىنى ئۆچۈرۈش
        for (let i = 0; i < qubitCount; i++) {
          if (currentStep[`q${i}`] === 'CNOT-CONTROL' || currentStep[`q${i}`] === 'CNOT-TARGET' || currentStep[`q${i}`] === 'SWAP') {
            currentStep[`q${i}`] = null;
          }
        }
      } else {
        currentStep[qubitId] = null;
      }
      
      newSteps[stepIdx] = currentStep;
      return newSteps;
    });
  };

  // پۈتۈن زەنجىرنى نۆللەشتۈرۈش
  const resetCircuit = () => {
    setSteps(Array(8).fill(null).map(() => {
      const step = {};
      for (let i = 0; i < qubitCount; i++) step[`q${i}`] = null;
      return step;
    }));
  };

  // زەنجىر ياكى كۇبىت سانى ئۆزگەرگەندە گرافىك ۋە كود ھاسىل قىلىش
  useEffect(() => {
    // 1. ئاكادېمىك ASCII گرافىك ھاسىل قىلىش
    let lines = Array(qubitCount).fill(null).map((_, i) => `q${i} ──`);
    let middleLines = Array(qubitCount - 1).fill(null).map(() => `     `);

    steps.forEach((step) => {
      // ھەر بىر كۇبىت لىنىيىسىنى بىر قۇر تەكشۈرۈپ چىقىش
      for (let i = 0; i < qubitCount; i++) {
        const gate = step[`q${i}`];
        if (gate === 'CNOT-CONTROL') {
          lines[i] += '─●─';
          if (i < qubitCount - 1 && step[`q${i+1}`] === 'CNOT-TARGET') middleLines[i] += ' │ ';
        } else if (gate === 'CNOT-TARGET') {
          lines[i] += '─X─';
        } else if (gate === 'SWAP') {
          lines[i] += '─×─';
          if (i < qubitCount - 1 && step[`q${i+1}`] === 'SWAP') middleLines[i] += ' │ ';
        } else {
          lines[i] += gate ? `[${gate === 'Measure' ? 'M' : gate}]` : '───';
          if (i < qubitCount - 1) middleLines[i] += '   ';
        }
        lines[i] += '──';
        if (i < qubitCount - 1) middleLines[i] += '  ';
      }
    });

    // لىنىيەلەرنى بىرلەشتۈرۈپ چىقىش
    let finalGraph = '';
    for (let i = 0; i < qubitCount; i++) {
      finalGraph += lines[i] + '\n';
      if (i < qubitCount - 1) {
        finalGraph += middleLines[i] + '\n';
      }
    }
    setTextResult(finalGraph);

    // 2. Qiskit Python كودى ھاسىل قىلىش
    let qiskitGates = '';
    steps.forEach((step) => {
      for (let i = 0; i < qubitCount; i++) {
        const gate = step[`q${i}`];
        if (gate === 'CNOT-CONTROL') {
          // ئاستىدىكى كۇبىت بىلەن باغلانغانلىقىنى جەزملەش
          if (step[`q${i+1}`] === 'CNOT-TARGET') qiskitGates += `qc.cx(${i}, ${i+1})\n`;
        } else if (gate === 'SWAP') {
          if (step[`q${i+1}`] === 'SWAP') qiskitGates += `qc.swap(${i}, ${i+1})\n`;
        } else if (gate && gate !== 'CNOT-TARGET') {
          if (gate === 'Measure') qiskitGates += `qc.measure(${i}, ${i})\n`;
          else qiskitGates += `qc.${gate.toLowerCase()}(${i})\n`;
        }
      }
    });

    const pyCodeTemplate = `# قۇراشتۇرۇلغان كەسپىي كۋانت زەنجىرى كودى (Qiskit 1.0+)
from qiskit import QuantumCircuit
from qiskit_aer import AerSimulator

# ${qubitCount} كۇبىت ۋە ${qubitCount} كلاسسىك بىتلىق زەنجىر ھەرىكەتچان قۇرۇلدى
qc = QuantumCircuit(${qubitCount}, ${qubitCount})

# كۋانت دەرۋازىلىرى
${qiskitGates || '# ھازىرچە دەرۋازا تاشلانمىدى\n'}
# زەنجىرنى سىمتىن سىزىپ كۆرۈش
print("--- كۋانت زەنجىرى گرافىكى ---")
print(qc.draw(output='text'))

# سىمۇلياتوردا ئىجرا قىلىش
simulator = AerSimulator()
job = simulator.run(qc, shots=1024)
result = job.result()
counts = result.get_counts()

print("\\n--- ئۆلچەش نەتىجىسى (Counts) ---")
print(counts)
`;
    setPythonCode(pyCodeTemplate);
  }, [steps, qubitCount]);

  const copyToClipboard = () => {
    navigator.clipboard.writeText(pythonCode);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="space-y-6 text-right" dir="rtl">
      
      {/* دەرۋازا تاللاش قوراللىرى */}
      <QuantumToolbar />

      {/* ئاساسلىق كەسپىي سىمۇلياتور مەيدانى */}
      <div className="bg-white dark:bg-slate-900 p-6 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-xl relative overflow-hidden">
        <div className="absolute top-0 right-0 left-0 h-[4px] bg-gradient-to-r from-blue-500 via-indigo-500 to-purple-500"></div>
        
        {/* كۇبىت باشقۇرۇش ۋە نۆللەشتۈرۈش بالدىقى */}
        <div className="flex flex-col sm:flex-row justify-between items-center mb-6 pt-2 gap-4">
          <div className="flex gap-2" dir="ltr">
            <button 
              onClick={resetCircuit} 
              className="px-3 py-1.5 bg-slate-100 hover:bg-slate-200 dark:bg-slate-800 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-300 rounded-xl text-xs font-bold transition-all"
            >
              Reset
            </button>
            <button 
              onClick={removeQubit} 
              disabled={qubitCount <= 1}
              className="px-3 py-1.5 bg-rose-50 text-rose-600 hover:bg-rose-100 dark:bg-rose-950/30 dark:text-rose-400 rounded-xl text-xs font-bold transition-all disabled:opacity-40"
            >
              ✕ كۇبىت ئۆچۈرۈش
            </button>
            <button 
              onClick={addQubit} 
              disabled={qubitCount >= 8}
              className="px-3 py-1.5 bg-emerald-50 text-emerald-600 hover:bg-emerald-100 dark:bg-emerald-950/30 dark:text-emerald-400 rounded-xl text-xs font-bold transition-all disabled:opacity-40"
            >
              ＋ كۇبىت قوشۇش ({qubitCount})
            </button>
          </div>
          <div className="text-center sm:text-right">
            <h3 className="text-base font-extrabold text-slate-800 dark:text-white">Multi-Qubit Quantum Composer</h3>
            <p className="text-[11px] text-slate-400">كۇبىت سانىنى خالىغانچە كۆپەيتىڭ ياكى ئۆچۈرۈڭ (ئەڭ كۆپ بولغاندا 8 كۇبىت)</p>
          </div>
        </div>

        {/* كۋانت تورلۇق زەنجىر لايىھەلىگۈچى قىسمى */}
        <div className="overflow-x-auto py-6 px-2 bg-slate-50 dark:bg-slate-950 rounded-2xl border border-slate-100 dark:border-slate-850" dir="ltr">
          <div className="min-w-[750px] space-y-7 relative">
            
            {/* ھەر بىر كۇبىت لىنىيىسىنى ھەرىكەتچان رېندېر قىلىش */}
            {Array(qubitCount).fill(null).map((_, qIdx) => {
              const qubitId = `q${qIdx}`;
              return (
                <div key={qubitId} className="flex items-center relative h-14">
                  <div className="w-14 font-mono font-bold text-indigo-500 dark:text-indigo-400 text-left pl-2 text-sm">{qubitId}</div>
                  {/* ئارقا تەرەپتىكى سىم سىزىقى */}
                  <div className="absolute left-14 right-0 h-[2px] bg-slate-200 dark:bg-slate-800 top-1/2 transform -translate-y-1/2 z-0"></div>
                  
                  {/* 8 تور كاتەكچىسى */}
                  <div className="flex-1 grid grid-cols-8 gap-3 z-10 pl-4">
                    {steps.map((step, idx) => {
                      const gate = step[qubitId];
                      return (
                        <div
                          key={`${qubitId}-${idx}`}
                          onDragOver={handleDragOver}
                          onDrop={(e) => handleDrop(e, qubitId, idx)}
                          className={`h-14 rounded-xl border border-dashed flex items-center justify-center relative group transition-all duration-200
                            ${gate ? 'border-transparent' : 'border-slate-300 dark:border-slate-700 hover:border-indigo-400 bg-white/60 dark:bg-slate-900/40'}
                          `}
                        >
                          {gate && (
                            <div 
                              onClick={() => removeGate(qubitId, idx)}
                              className={`w-11 h-11 rounded-xl text-white font-extrabold text-xs flex items-center justify-center cursor-pointer shadow-md transform hover:scale-105 active:scale-95 transition-all relative
                                ${gate.startsWith('CNOT') ? 'bg-indigo-600' : gate === 'SWAP' ? 'bg-orange-500' : gate === 'H' ? 'bg-blue-500' : gate === 'Measure' ? 'bg-slate-700' : 'bg-emerald-500'}
                              `}
                            >
                              {gate === 'CNOT-CONTROL' ? '●' : gate === 'CNOT-TARGET' ? '⊕' : gate === 'SWAP' ? '×' : gate === 'Measure' ? 'M' : gate}
                              <span className="absolute -top-1 -right-1 bg-rose-500 text-white w-4 h-4 rounded-full text-[9px] flex items-center justify-center opacity-0 group-hover:opacity-100 transition shadow">✕</span>
                            </div>
                          )}
                        </div>
                      );
                    })}
                  </div>
                </div>
              );
            })}

            {/* ھەرىكەتچان جىسمانىي باغلىنىش لىنىيەسىنى ئۈستىگە سىزىش قەۋىتى */}
            <div className="absolute left-14 right-0 top-0 bottom-0 pointer-events-none z-20 grid grid-cols-8 gap-3 pl-4">
              {steps.map((step, idx) => {
                // تۈۋرۈك بويىچە بىرىنچى ئۆتكەن CNOT ياكى SWAP نى تېپىش ۋە جىسمانىي لىنىيە تارتىش
                let startQIdx = -1;
                let endQIdx = -1;

                for (let i = 0; i < qubitCount; i++) {
                  const gate = step[`q${i}`];
                  if (gate === 'CNOT-CONTROL' || (gate === 'SWAP' && startQIdx === -1)) {
                    startQIdx = i;
                  }
                  if (gate === 'CNOT-TARGET' || (gate === 'SWAP' && startQIdx !== -1 && i !== startQIdx)) {
                    endQIdx = i;
                    break;
                  }
                }

                if (startQIdx !== -1 && endQIdx !== -1) {
                  // تورنىڭ يۇقىرىدىن تۆۋەنگە بولغان ئارىلىقىنى ھېسابلاپ يۆنىلىش سىزىش
                  const topPos = startQIdx * 84 + 28; // ھەر بىر قۇرنىڭ بوشلۇقىغا ئاساسەن
                  const height = (endQIdx - startQIdx) * 84;
                  return (
                    <div key={`link-${idx}`} className="relative h-full">
                      <div 
                        className="absolute w-[2px] bg-gradient-to-b from-indigo-500 via-purple-500 to-pink-500 left-1/2 transform -translate-x-1/2"
                        style={{ top: `${topPos}px`, height: `${height}px` }}
                      ></div>
                    </div>
                  );
                }
                return <div key={`link-${idx}`}></div>;
              })}
            </div>

          </div>
        </div>
      </div>

      {/* چىقىرىش بۆلۈمى */}
      <div className="grid md:grid-cols-2 gap-6">
        
        {/* ئاكادېمىك تېكىستلىك نەتىجە (ASCII Graphic) */}
        <div className="bg-slate-950 text-indigo-400 p-5 rounded-2xl font-mono text-xs shadow-2xl relative border border-slate-800" dir="ltr">
          <span className="absolute top-3 right-3 text-[10px] text-slate-500 font-sans tracking-wider uppercase font-bold">ASCII Diagram</span>
          <h4 className="text-slate-400 text-xs font-sans mb-4 font-bold text-left">نەق مەيدان كۋانت سىگنالى گرافىكى:</h4>
          <pre className="whitespace-pre overflow-x-auto leading-relaxed bg-slate-900/50 p-4 rounded-xl border border-slate-900 text-left custom-scrollbar">
            {textResult}
          </pre>
        </div>

        {/* پروپېسسىيۆنال Qiskit Python كود رايونى */}
        <div className="bg-slate-950 text-emerald-400 p-5 rounded-2xl font-mono text-xs shadow-2xl relative border border-slate-800" dir="ltr">
          <div className="absolute top-3 right-3 flex items-center gap-2">
            <button 
              onClick={copyToClipboard}
              className={`px-2.5 py-1 text-[10px] font-sans font-bold rounded-md transition-all
                ${copied ? 'bg-emerald-500 text-slate-950' : 'bg-slate-800 text-slate-300 hover:bg-slate-700'}
              `}
            >
              {copied ? '✓ Copied!' : '📋 Copy Code'}
            </button>
            <span className="text-[10px] text-slate-500 font-sans tracking-wider uppercase font-bold">Qiskit Script</span>
          </div>
          <h4 className="text-slate-400 text-xs font-sans mb-4 font-bold text-left">ئىجرا قىلىشقا تەييار كود (Python):</h4>
          <pre className="whitespace-pre overflow-x-auto text-left leading-5 bg-slate-900/50 p-4 rounded-xl border border-slate-900 max-h-[190px] overflow-y-auto custom-scrollbar text-emerald-300/95">
            {pythonCode}
          </pre>
        </div>

      </div>
    </div>
  );
}