import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  RotateCcw, Play, CheckCircle, ArrowLeft, 
  GraduationCap, Search, Video, 
  FileText, ExternalLink, RefreshCw, Layers, BookOpen
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import lessonsData from '../data/lessons.json';

export default function LessonsPage() {
  const navigate = useNavigate();
  
  // ھالەت باشقۇرۇش سىستېمىسى
  const [albums, setAlbums] = useState([]);
  const [filteredAlbums, setFilteredAlbums] = useState([]);
  const [currentAlbum, setCurrentAlbum] = useState(null);
  const [currentLesson, setCurrentLesson] = useState(null);
  const [progress, setProgress] = useState({});
  const [searchQuery, setSearchQuery] = useState('');
  const [playbackRate, setPlaybackRate] = useState(1); 

  const videoRef = useRef(null);

  // 1. مەلۇماتلارنى دەسلەپتە يۈكلەش
  useEffect(() => {
    setAlbums(lessonsData);
    setFilteredAlbums(lessonsData);

    const savedProgress = localStorage.getItem('kelbil_quantum_progress');
    if (savedProgress) {
      setProgress(JSON.parse(savedProgress));
    }
  }, []);

  // 2. ئەقلىي ئىقتىدارلىق ئىزدەش سىستېمىسى (ئىچكى دەرس مەزمۇنلىرىغىچە سۈزىدۇ)
  useEffect(() => {
    if (searchQuery.trim() === '') {
      setFilteredAlbums(albums);
      return;
    }

    const query = searchQuery.toLowerCase();
    const result = albums.map(album => {
      // ئەگەر ئەلبۇم ماۋزۇسى ماس كەلسە، ھەممە دەرىسنى ساقلايدۇ
      if (album.title.toLowerCase().includes(query)) {
        return album;
      }
      // بولمىسا، ئىچىدىكى ماس كېلىدىغان دەرسلەرنىلا سۈزىدۇ
      const matchedLessons = album.lessons.filter(lesson => 
        lesson.title.toLowerCase().includes(query) || 
        lesson.desc.toLowerCase().includes(query)
      );
      
      if (matchedLessons.length > 0) {
        return { ...album, lessons: matchedLessons };
      }
      return null;
    }).filter(Boolean);

    setFilteredAlbums(result);
  }, [searchQuery, albums]);

  // 3. MP4 ۋىدىئو ئىلگىرىلەش پىرسەنتىنى ئاپتوماتىك ساقلاش
  const handleTimeUpdate = () => {
    if (!videoRef.current || !currentLesson || currentLesson.youtube) return;
    
    const currentTime = videoRef.current.currentTime;
    const duration = videoRef.current.duration;
    if (duration > 0) {
      const percentage = Math.round((currentTime / duration) * 100);
      const updatedProgress = {
        ...progress,
        [currentLesson.title]: { currentTime, percentage }
      };
      setProgress(updatedProgress);
      localStorage.setItem('kelbil_quantum_progress', JSON.stringify(updatedProgress));
    }
  };

  // 4. ۋىدىئو يۈكلەنگەندە قالغان ئورۇندىن باشلاش
  const handleLoadedMetadata = () => {
    if (!videoRef.current || !currentLesson || currentLesson.youtube) return;
    const saved = progress[currentLesson.title];
    if (saved && saved.currentTime) {
      videoRef.current.currentTime = saved.currentTime;
    }
    videoRef.current.playbackRate = playbackRate;
  };

  // يۇتۇب ياكى باشقا دەرسنى تاللىغاندا ئىلگىرىلەشنى تاماملامدى دەپ بەلگىلەش
  const markAsCompleted = (lessonTitle) => {
    const updatedProgress = {
      ...progress,
      [lessonTitle]: { currentTime: 0, percentage: 100 }
    };
    setProgress(updatedProgress);
    localStorage.setItem('kelbil_quantum_progress', JSON.stringify(updatedProgress));
  };

  const changeSpeed = (speed) => {
    setPlaybackRate(speed);
    if (videoRef.current) {
      videoRef.current.playbackRate = speed;
    }
  };

  const restartVideo = () => {
    if (videoRef.current) {
      videoRef.current.currentTime = 0;
      videoRef.current.play();
    }
  };

  // 5. بىخەتەرلىك قوغداش قەۋىتى
  useEffect(() => {
    const preventActions = (e) => e.preventDefault();
    document.addEventListener('contextmenu', preventActions);
    document.addEventListener('copy', preventActions);
    return () => {
      document.removeEventListener('contextmenu', preventActions);
      document.removeEventListener('copy', preventActions);
    };
  }, []);

  // بىر ئەلبۇمنىڭ ئومۇمىي ئۆگىنىش پىرسەنتىنى ھېسابلاش فۇنكسىيەسى
  const calculateAlbumProgress = (albumLessons) => {
    if (!albumLessons || albumLessons.length === 0) return 0;
    let totalPercentage = 0;
    albumLessons.forEach(l => {
      totalPercentage += progress[l.title]?.percentage || 0;
    });
    return Math.round(totalPercentage / albumLessons.length);
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 p-4 md:p-10 select-none font-sans" style={{ userSelect: 'none' }}>
      
      {/* ئەڭ ئۈستىدىكى قايتىش ۋە نېۋىگاتور قىسمى */}
      <div className="max-w-7xl mx-auto flex flex-row-reverse justify-between items-center mb-8 border-b border-slate-900 pb-5">
        <button 
          onClick={() => {
            if (currentLesson) {
              setCurrentLesson(null);
            } else if (currentAlbum) {
              setCurrentAlbum(null);
            } else {
              navigate(-1);
            }
          }}
          className="flex items-center gap-2 text-sm bg-slate-900 hover:bg-slate-800 border border-slate-800 text-slate-300 px-5 py-2.5 rounded-xl transition duration-300"
        >
          <ArrowLeft className="w-4 h-4" /> كەينىگە قايتىش
        </button>

        <div className="flex items-center gap-3 bg-gradient-to-l from-blue-600/10 to-transparent p-2 rounded-lg border-l-4 border-blue-500 pl-4">
          <span className="text-xs tracking-widest text-blue-400 font-mono">KeLBiL ACADEMY v3.0</span>
          <GraduationCap className="w-6 h-6 text-blue-400" />
        </div>
      </div>

      {/* ----------------- 1-ھالەت: ئاساسىي ئەلبۇملار تىزىملىكى ----------------- */}
      {!currentAlbum && !currentLesson && (
        <div className="max-w-7xl mx-auto space-y-8">
          
          {/* شۇئار قىسمى */}
          <div className="text-center space-y-3 max-w-3xl mx-auto py-4">
            <h1 className="text-3xl md:text-5xl font-black bg-gradient-to-r from-white via-slate-200 to-slate-400 bg-clip-text text-transparent">
              كۋانت تېخنىكىسى ئۆگىنىش سۇپىسى
            </h1>
            <p className="text-sm md:text-md text-blue-400 font-light italic">
              "تۆھپە تىلدا، تېخىمۇ كۈچلۈك روھ بىلەن بىلىمگە يول!"
            </p>
          </div>

          {/* ئىزدەش تاختىسى */}
          <div className="bg-slate-900/40 border border-slate-900 p-4 rounded-2xl max-w-xl mx-auto backdrop-blur-xl">
            <div className="relative">
              <Search className="absolute right-4 top-3.5 w-4 h-4 text-slate-500" />
              <input 
                type="text" 
                placeholder="ئەلبۇم ياكى دەرسلەرنى ئىزداڭ..." 
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full bg-slate-950 border border-slate-800 rounded-xl py-3 pr-11 pl-4 text-sm text-slate-200 placeholder-slate-500 focus:outline-none focus:border-blue-500 transition text-right"
              />
            </div>
          </div>

          {/* ئەلبۇملار ئېكرانى (Grid) */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            <AnimatePresence>
              {filteredAlbums.map((album) => {
                const albumProgress = calculateAlbumProgress(album.lessons);
                return (
                  <motion.div
                    key={album.id}
                    layout
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0 }}
                    whileHover={{ y: -5 }}
                    onClick={() => setCurrentAlbum(album)}
                    className="bg-slate-900/80 border border-slate-800/80 rounded-2xl p-6 cursor-pointer hover:border-blue-500/40 transition-all duration-300 text-right flex flex-col justify-between space-y-4"
                  >
                    <div className="space-y-2">
                      <div className="w-12 h-12 rounded-xl bg-blue-600/10 border border-blue-500/20 flex items-center justify-center mb-4 ml-auto">
                        <Layers className="w-6 h-6 text-blue-400" />
                      </div>
                      <h3 className="text-lg font-bold text-slate-100 hover:text-blue-400 transition-colors">
                        {album.title}
                      </h3>
                      <p className="text-xs text-slate-400 font-light">
                        بۇ ئەلبۇم جەمئىي <span className="text-blue-400 font-bold">{album.lessons.length}</span> دانە يۇقىرى دەرىجىلىك دەرسنى ئۆز ئىچىگە ئالىدۇ.
                      </p>
                    </div>

                    {/* ئىلگىرىلەش بالدىقى */}
                    <div className="pt-4 border-t border-slate-800/60">
                      <div className="flex justify-between items-center text-[11px] text-slate-500 mb-1.5 font-mono">
                        {albumProgress === 100 ? (
                          <span className="text-emerald-400 flex items-center gap-1"><CheckCircle className="w-3 h-3" /> تاماملىندى</span>
                        ) : (
                          <span>{albumProgress}% ئۆگىنىلدى</span>
                        )}
                        <span className="bg-slate-950 px-2 py-0.5 rounded border border-slate-800 text-[10px]">ROLE: {album.allowedRoles?.[1] || 'user'}</span>
                      </div>
                      <div className="w-full bg-slate-950 h-1.5 rounded-full overflow-hidden">
                        <div className="bg-gradient-to-r from-blue-600 to-cyan-400 h-full transition-all duration-500" style={{ width: `${albumProgress}%` }} />
                      </div>
                    </div>
                  </motion.div>
                );
              })}
            </AnimatePresence>
          </div>
        </div>
      )}

      {/* ----------------- 2-ھالەت: ئەلبۇم ئىچىدىكى دەرسلەر مۇندەرىجىسى ----------------- */}
      {currentAlbum && !currentLesson && (
        <div className="max-w-4xl mx-auto space-y-6">
          <div className="flex flex-row-reverse justify-between items-center bg-slate-900/40 p-4 rounded-xl border border-slate-800 text-right">
            <div>
              <h2 className="text-xl font-extrabold text-blue-400">{currentAlbum.title}</h2>
              <p className="text-xs text-slate-400 mt-1">تۆۋەندىكى دەرسلەرنى تاللاپ ئۆگىنىشنى باشلاڭ</p>
            </div>
            <button 
              onClick={() => setCurrentAlbum(null)}
              className="text-xs bg-slate-950 hover:bg-slate-900 px-3 py-1.5 rounded-lg border border-slate-800 text-slate-400"
            >
              ئەلبۇملارغا قايتىش
            </button>
          </div>

          <div className="space-y-3">
            {currentAlbum.lessons.map((lesson, idx) => {
              const lessonProgress = progress[lesson.title]?.percentage || 0;
              return (
                <motion.div
                  key={idx}
                  whileHover={{ x: -4 }}
                  onClick={() => setCurrentLesson(lesson)}
                  className="bg-slate-900 border border-slate-800/60 p-4 rounded-xl cursor-pointer hover:border-blue-500/40 flex flex-row-reverse justify-between items-center text-right gap-4 transition duration-200"
                >
                  <div className="flex flex-row-reverse items-center gap-4">
                    <div className="w-10 h-10 rounded-lg bg-slate-950 border border-slate-800 flex items-center justify-center flex-shrink-0 text-blue-400 font-mono text-sm font-bold">
                      {idx + 1}
                    </div>
                    <div>
                      <h4 className="text-md font-bold text-slate-200 hover:text-blue-400 transition-colors">{lesson.title}</h4>
                      <p className="text-xs text-slate-400 font-light mt-1 line-clamp-1">{lesson.desc}</p>
                    </div>
                  </div>

                  <div className="flex items-center gap-3">
                    {lessonProgress === 100 ? (
                      <CheckCircle className="w-5 h-5 text-emerald-400 flex-shrink-0" />
                    ) : lessonProgress > 0 ? (
                      <span className="text-xs font-mono text-blue-400 bg-blue-500/10 px-2 py-0.5 rounded border border-blue-500/20">{lessonProgress}%</span>
                    ) : (
                      <Play className="w-4 h-4 text-slate-500 fill-current" />
                    )}
                  </div>
                </motion.div>
              );
            })}
          </div>
        </div>
      )}

      {/* ----------------- 3-ھالەت: كۈچەيتىلگەن كەسپىي قويغۇچ ئېكرانى ----------------- */}
      {currentLesson && (
        <div className="max-w-7xl mx-auto grid grid-cols-1 lg:grid-cols-3 gap-8 mt-4">
          
          {/* سول تەرەپ: ۋىدىئو ئېكرانى ۋە ماتېرىيال قوراللىرى */}
          <div className="lg:col-span-2 space-y-6">
            <div className="bg-slate-900 rounded-2xl overflow-hidden border border-slate-800/80 shadow-2xl">
              
              {/* ئېكران قىسمى */}
              <div className="relative aspect-video bg-black select-none">
                {currentLesson.youtube ? (
                  <iframe
                    src={`${currentLesson.youtube}?rel=0&modestbranding=1&controls=1`}
                    title={currentLesson.title}
                    className="w-full h-full"
                    allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture"
                    allowFullScreen
                    onLoad={() => markAsCompleted(currentLesson.title)}
                  ></iframe>
                ) : currentLesson.video ? (
                  <video
                    ref={videoRef}
                    src={currentLesson.video}
                    controls
                    controlsList="nodownload"
                    onTimeUpdate={handleTimeUpdate}
                    onLoadedMetadata={handleLoadedMetadata}
                    className="w-full h-full object-contain"
                  />
                ) : (
                  <div className="w-full h-full flex flex-col items-center justify-center text-slate-500 p-6 text-center space-y-2">
                    <Video className="w-12 h-12 text-slate-700" />
                    <p className="text-sm">بۇ دەرسكە ۋىدىئو تەمىنلەنمىگەن، تۆۋەندىكى ئەقلىي ماتېرىياللار ئارقىلىق ئۆگىنىڭ.</p>
                  </div>
                )}
                
                <div className="absolute top-4 left-4 bg-black/70 backdrop-blur-md px-3 py-1 rounded-lg border border-slate-800 pointer-events-none">
                  <span className="text-[10px] text-blue-400 font-mono tracking-wider">SECURE STREAM</span>
                </div>
              </div>

              {/* دەرس تەپسىلاتى ۋە قورال تاختىلىرى */}
              <div className="p-6 space-y-6 text-right">
                <div className="flex flex-row-reverse flex-wrap justify-between items-center gap-4 border-b border-slate-800 pb-4">
                  <div>
                    <span className="text-[10px] bg-blue-950 text-blue-400 border border-blue-900 font-bold px-2.5 py-1 rounded-md font-mono">
                      KeLBiL COURSE
                    </span>
                    <h2 className="text-2xl font-black mt-2 text-slate-100">{currentLesson.title}</h2>
                  </div>

                  {/* تېزلىك كونتروللىرى (پەقەت MP4 دە كۆرۈنىدۇ) */}
                  {currentLesson.video && !currentLesson.youtube && (
                    <div className="flex items-center gap-3 bg-slate-950 p-2 rounded-xl border border-slate-800">
                      <div className="flex gap-1">
                        {[0.5, 1, 1.5, 2].map((speed) => (
                          <button
                            key={speed}
                            onClick={() => changeSpeed(speed)}
                            className={`px-2 py-0.5 rounded-md text-xs font-mono transition ${
                              playbackRate === speed ? 'bg-blue-500 text-slate-950 font-bold' : 'text-slate-400 hover:text-slate-200'
                            }`}
                          >
                            {speed}x
                          </button>
                        ))}
                      </div>
                      <div className="w-px h-3 bg-slate-800" />
                      <button onClick={restartVideo} className="p-1 bg-slate-900 text-slate-400 hover:text-slate-200 rounded">
                        <RotateCcw className="w-3 h-3" />
                      </button>
                    </div>
                  )}
                </div>

                <p className="text-slate-400 text-sm font-light leading-relaxed">
                  {currentLesson.desc}
                </p>

                {/* 📂 قوشۇمچە دەرسلىك ماتېرىياللىرى (PDF & HTML) قىسمى */}
                {(currentLesson.pdf || currentLesson.html) && (
                  <div className="pt-4 border-t border-slate-800/60 space-y-3">
                    <h3 className="text-sm font-bold text-slate-300 flex flex-row-reverse items-center gap-2">
                      <BookOpen className="w-4 h-4 text-blue-400" /> قوشۇمچە ئۆگىنىش بايلىقلىرى:
                    </h3>
                    <div className="flex flex-row-reverse flex-wrap gap-3">
                      {currentLesson.pdf && (
                        <a 
                          href={currentLesson.pdf} 
                          target="_blank" 
                          rel="noreferrer"
                          onClick={() => markAsCompleted(currentLesson.title)}
                          className="flex items-center gap-2 text-xs bg-red-950/40 hover:bg-red-950/60 border border-red-900/50 text-red-400 px-4 py-2.5 rounded-xl transition"
                        >
                          <FileText className="w-4 h-4" /> PDF دەرسلىكنى چۈشۈرۈش / كۆرۈش
                        </a>
                      )}
                      {currentLesson.html && (
                        <a 
                          href={currentLesson.html} 
                          target="_blank" 
                          rel="noreferrer"
                          onClick={() => markAsCompleted(currentLesson.title)}
                          className="flex items-center gap-2 text-xs bg-slate-950 hover:bg-slate-800 border border-slate-800 text-cyan-400 px-4 py-2.5 rounded-xl transition"
                        >
                          <ExternalLink className="w-4 h-4" /> ئەقلىي ئىقتىدارلىق HTML كۆرۈنۈشى
                        </a>
                      )}
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>

          {/* ئوڭ تەرەپ: شۇ ئەلبۇم ئىچىدىكى تىك قۇر مۇندەرىجىسى */}
          <div className="space-y-4">
            <div className="flex flex-row-reverse justify-between items-center border-l-4 border-blue-500 pl-3">
              <h2 className="text-lg font-bold text-right">ئەلبۇمدىكى دەرسلەر</h2>
              <span className="text-[10px] text-slate-500 font-mono">PLAYLIST</span>
            </div>
            
            <div className="space-y-3 max-h-[70vh] overflow-y-auto pr-1">
              {(currentAlbum ? currentAlbum.lessons : albums.flatMap(a => a.lessons)).map((lesson, index) => {
                const lessonProgress = progress[lesson.title]?.percentage || 0;
                const isSelected = currentLesson?.title === lesson.title;

                return (
                  <motion.div
                    key={index}
                    whileHover={{ x: -3 }}
                    onClick={() => setCurrentLesson(lesson)}
                    className={`p-3.5 rounded-xl cursor-pointer transition border text-right flex flex-row-reverse items-center justify-between gap-4 ${
                      isSelected 
                        ? 'bg-gradient-to-l from-blue-950/30 to-slate-900 border-blue-500/80 shadow-md shadow-blue-500/5' 
                        : 'bg-slate-900/60 hover:bg-slate-900 border-slate-900'
                    }`}
                  >
                    <div className="flex flex-row-reverse items-center gap-3 min-w-0">
                      <div className={`w-8 h-8 rounded-lg flex items-center justify-center flex-shrink-0 font-mono text-xs font-bold ${
                        isSelected ? 'bg-blue-500 text-slate-950' : 'bg-slate-950 border border-slate-800 text-slate-400'
                      }`}>
                        {index + 1}
                      </div>
                      <div className="min-w-0">
                        <h4 className={`text-xs font-bold truncate ${isSelected ? 'text-blue-400' : 'text-slate-200'}`}>
                          {lesson.title}
                        </h4>
                        <p className="text-[10px] text-slate-500 truncate mt-0.5 font-light">{lesson.desc}</p>
                      </div>
                    </div>

                    <div className="flex items-center">
                      {lessonProgress === 100 ? (
                        <CheckCircle className="w-4 h-4 text-emerald-400" />
                      ) : (
                        <Play className={`w-3 h-3 ${isSelected ? 'text-blue-400 scale-110 fill-current' : 'text-slate-600'}`} />
                      )}
                    </div>
                  </motion.div>
                );
              })}
            </div>
          </div>

        </div>
      )}
    </div>
  );
}