import React, { useState, useEffect } from 'react';
import { Brain, Sparkles, Key, Send, RotateCcw, Eye, EyeOff, CheckCircle, ShieldCheck, PlusCircle, Trash2, Globe } from 'lucide-react';

const ModelsTab = ({ 
  selectedModels, 
  setSelectedModels, 
  modelsInput, 
  setModelsInput, 
  modelsOutput, 
  setModelsOutput, 
  loading, 
  handleModelQuery, 
  apiKeys, 
  setApiKeys 
}) => {
  
  // 1. ئۆز ئىچىگە ئالغان ئاساسىي بەش مودېل + QutadghuAI
  const defaultModels = [
    { id: 'qutadghu-ai', name: 'QutadghuAI (قۇتادغۇ)', provider: 'Local/Custom', icon: '📜', color: 'from-amber-600 to-red-700', keyType: 'qutadghu' },
    { id: 'gpt-4o', name: 'GPT-4o', provider: 'OpenAI', icon: '🧠', color: 'from-emerald-500 to-teal-600', keyType: 'openai' },
    { id: 'claude-3-5-sonnet', name: 'Claude 3.5 Sonnet', provider: 'Anthropic', icon: '🦅', color: 'from-orange-500 to-amber-600', keyType: 'anthropic' },
    { id: 'gemini-1.5-pro', name: 'Gemini 1.5 Pro', provider: 'Google', icon: '✨', color: 'from-blue-500 to-indigo-600', keyType: 'google' },
    { id: 'sonar-reasoning', name: 'Sonar Reasoning', provider: 'Perplexity', icon: '🔍', color: 'from-cyan-500 to-blue-600', keyType: 'perplexity' },
    { id: 'grok-2', name: 'Grok 2', provider: 'xAI', icon: '⬛', color: 'from-slate-700 to-black', keyType: 'xai' }
  ];

  // يەرلىك ھالەتلەر
  const [availableModels, setAvailableModels] = useState(defaultModels);
  const [showKeys, setShowKeys] = useState({});
  
  // يېڭى مودېل قوشۇش ھالىتى (مەسلەن: DeepSeek ئۈچۈن)
  const [customModelForm, setCustomModelForm] = useState({ name: '', id: '', provider: '', baseUrl: '', keyType: 'custom_api' });
  const [showCustomModal, setShowCustomModal] = useState(false);

  // تېكىستنىڭ ئۇيغۇرچە ياكى ئەمەسلىكىنى (RTL) ئاپتوماتىك تەكشۈرۈش فۇنكسىيەسى
  const isUyghurText = (text) => {
    if (!text) return true; // ئۇيغۇرچە دەپ تۇرۇش پاتى پاتى
    const uyghurRegex = /[\u0600-\u06FF\uFB50-\uFDFF\uFE70-\uFEFF]/;
    return uyghurRegex.test(text);
  };

  // 2. بەت قوزغالغاندا كۇنۇپكىلارنى ۋە ئىختىيارىي مودېللارنى لوكاندىن ئوقۇش
  useEffect(() => {
    const savedKeys = localStorage.getItem('__ai_matrix_keys');
    if (savedKeys) {
      try { setApiKeys(JSON.parse(savedKeys)); } catch (e) { console.error(e); }
    }

    const savedCustomModels = localStorage.getItem('__ai_custom_models');
    if (savedCustomModels) {
      try {
        const parsed = JSON.parse(savedCustomModels);
        setAvailableModels([...defaultModels, ...parsed]);
      } catch (e) { console.error(e); }
    }
  }, [setApiKeys]);

  // API ئاچقۇچ ساقلاش
  const handleKeyChange = (keyType, value) => {
    const updatedKeys = { ...apiKeys, [keyType]: value };
    setApiKeys(updatedKeys);
    localStorage.setItem('__ai_matrix_keys', JSON.stringify(updatedKeys));
  };

  // يېڭى ئىختىيارىي مودېل قوشۇش (DeepSeek قاتارلىقلار)
  const handleAddCustomModel = (e) => {
    e.preventDefault();
    if (!customModelForm.name || !customModelForm.id) return;

    const newModel = {
      id: customModelForm.id.trim(),
      name: customModelForm.name.trim(),
      provider: customModelForm.provider.trim() || 'Custom Provider',
      icon: '🌐',
      color: 'from-purple-500 to-indigo-600',
      keyType: `key_${customModelForm.id.trim()}`,
      baseUrl: customModelForm.baseUrl.trim()
    };

    const updatedCustoms = [...availableModels.filter(m => !defaultModels.some(d => d.id === m.id)), newModel];
    localStorage.setItem('__ai_custom_models', JSON.stringify(updatedCustoms));
    
    setAvailableModels([...defaultModels, ...updatedCustoms]);
    setShowCustomModal(false);
    setCustomModelForm({ name: '', id: '', provider: '', baseUrl: '', keyType: 'custom_api' });
  };

  // ئىختىيارىي قوشۇلغان مودېلنى ئۆچۈرۈش
  const handleDeleteModel = (modelId, e) => {
    e.stopPropagation(); // كارتىنىڭ تاللىنىپ كېتىشىنى توسىدۇ
    const filtered = availableModels.filter(m => m.id !== modelId);
    setAvailableModels(filtered);
    
    const customsOnly = filtered.filter(m => !defaultModels.some(d => d.id === m.id));
    localStorage.setItem('__ai_custom_models', JSON.stringify(customsOnly));
    
    if (selectedModels.includes(modelId)) {
      setSelectedModels(selectedModels.filter(id => id !== modelId));
    }
  };

  const toggleKeyVisibility = (keyType) => {
    setShowKeys(prev => ({ ...prev, [keyType]: !prev[keyType] }));
  };

  const handleClear = () => {
    setModelsInput('');
    setModelsOutput([]);
  };

  const toggleModel = (modelId) => {
    if (selectedModels.includes(modelId)) {
      setSelectedModels(selectedModels.filter(id => id !== modelId));
    } else {
      setSelectedModels([...selectedModels, modelId]);
    }
  };

  const isKeyConfigured = (keyType) => {
    return apiKeys[keyType] && apiKeys[keyType].trim().length > 5;
  };

  return (
    <div className="bg-slate-50 dark:bg-slate-900 rounded-3xl shadow-2xl p-6 md:p-10 border border-gray-200 dark:border-gray-800 transition-all duration-300">
      
      {/* 🌟 ئۈستى باشلىق قىسمى */}
      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6 mb-10 pb-8 border-b border-gray-200 dark:border-gray-800">
        <div className="flex items-center gap-4">
          <div className="p-4 bg-gradient-to-tr from-teal-500 via-blue-600 to-indigo-700 rounded-2xl text-white shadow-xl shadow-teal-500/20">
            <Brain className="w-9 h-9" />
          </div>
          <div>
            <h2 className="text-3xl font-black tracking-tight text-gray-900 dark:text-white">
              AI Models Matrix Control
            </h2>
            <p className="text-gray-500 dark:text-gray-400 text-base mt-1">
              يۇقىرى ئىقتىدارلىق كۆپ پىروۋايدېرلىق سۈنئىي ئىدراك مودېللىرىنى تەڭلا سېلىشتۇرۇش سىستېمىسى
            </p>
          </div>
        </div>
        
        <div className="flex items-center gap-3 px-4 py-2 bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 rounded-xl text-sm font-bold self-start lg:self-center shadow-sm border border-emerald-500/20">
          <ShieldCheck className="w-5 h-5" />
          لوكالدا ساقلىنىدۇ (Secure Local Workspace)
        </div>
      </div>

      {/* 🔑 API كۇنۇپكىلارنى تەڭشەش رايونى (چوڭاقتىلدى) */}
      <div className="mb-10 p-6 bg-white dark:bg-slate-800/80 rounded-2xl border border-gray-200 dark:border-slate-700 shadow-md">
        <div className="flex items-center justify-between mb-5">
          <div className="flex items-center gap-2.5">
            <Key className="w-6 h-6 text-amber-500" />
            <h4 className="font-extrabold text-gray-900 dark:text-white text-lg">API Credentials Configuration</h4>
          </div>
        </div>
        
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-5">
          {availableModels.map((m) => (
            <div key={m.id} className="flex flex-col gap-2">
              <label className="text-sm font-bold text-gray-700 dark:text-gray-300 flex items-center justify-between px-1">
                <span>{m.name} Key</span>
                {isKeyConfigured(m.keyType) && (
                  <span className="text-xs text-emerald-500 flex items-center gap-1 font-bold">
                    <CheckCircle className="w-3.5 h-3.5" /> قوزغىتىلدى
                  </span>
                )}
              </label>
              <div className="relative">
                <input
                  type={showKeys[m.keyType] ? "text" : "password"}
                  placeholder={m.id === 'qutadghu-ai' ? "كەلگۈسى ئاچقۇچ كودى..." : "sk-..."}
                  value={apiKeys[m.keyType] || ''}
                  onChange={(e) => handleKeyChange(m.keyType, e.target.value)}
                  className={`w-full pl-4 pr-12 py-3 text-sm rounded-xl border transition-all bg-slate-50 dark:bg-slate-900 text-gray-900 dark:text-gray-100 ${
                    isKeyConfigured(m.keyType) ? 'border-emerald-500 focus:ring-emerald-500' : 'border-gray-200 dark:border-slate-700 focus:ring-teal-500'
                  }`}
                />
                <button
                  type="button"
                  onClick={() => toggleKeyVisibility(m.keyType)}
                  className="absolute inset-y-0 right-0 flex items-center pr-4 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300"
                >
                  {showKeys[m.keyType] ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* 🤖 مودېل تاللاش كارتىلىرى ۋە يېڭى مودېل قوشۇش */}
      <div className="mb-10">
        <div className="flex justify-between items-center mb-5">
          <h3 className="font-black text-gray-950 dark:text-white text-base uppercase tracking-wider flex items-center gap-2">
            <Sparkles className="w-5 h-5 text-purple-500" />
            1. Target Engines (سېلىشتۇرۇلىدىغان مودېللارنى تاللاڭ)
          </h3>
          
          <button
            onClick={() => setShowCustomModal(true)}
            className="flex items-center gap-2 px-4 py-2 text-sm font-bold bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl transition-all shadow-md transform hover:-translate-y-0.5"
          >
            <PlusCircle className="w-4 h-4" />
            ئىختىيارىي مودېل قوشۇش (DeepSeek...)
          </button>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-6 gap-5">
          {availableModels.map((model) => {
            const isSelected = selectedModels.includes(model.id);
            const hasApiKey = isKeyConfigured(model.keyType);
            const isCustom = !defaultModels.some(d => d.id === model.id);
            
            return (
              <button
                key={model.id}
                onClick={() => toggleModel(model.id)}
                className={`relative flex flex-col items-start p-6 rounded-2xl border-2 transition-all duration-300 text-right group select-none min-h-[140px] ${
                  isSelected
                    ? 'border-teal-500 bg-white dark:bg-slate-800 shadow-xl ring-4 ring-teal-500/10'
                    : 'border-gray-200 dark:border-slate-800 bg-white dark:bg-slate-800/40 hover:border-teal-400 dark:hover:border-slate-700'
                }`}
              >
                <div className={`absolute top-0 left-0 right-0 h-1.5 rounded-t-2xl bg-gradient-to-r ${model.color}`} />
                
                <div className="flex justify-between items-center w-full mt-1 mb-4">
                  <span className="text-3xl p-2 bg-slate-100 dark:bg-slate-900 rounded-xl group-hover:scale-110 transition-transform duration-200">
                    {model.icon}
                  </span>
                  <div className="flex items-center gap-2">
                    <div className={`w-3 h-3 rounded-full ${hasApiKey ? 'bg-emerald-500' : 'bg-rose-400'} `} />
                    {isCustom && (
                      <span 
                        onClick={(e) => handleDeleteModel(model.id, e)}
                        className="text-gray-400 hover:text-rose-500 p-1 rounded transition-colors"
                        title="ئۆچۈرۈش"
                      >
                        <Trash2 className="w-4 h-4" />
                      </span>
                    )}
                  </div>
                </div>
                
                <div className="text-base font-black text-gray-900 dark:text-white">
                  {model.name}
                </div>
                <div className="text-xs text-gray-400 dark:text-gray-500 mt-1 font-bold">
                  {model.provider}
                </div>

                {isSelected && (
                  <div className="absolute -bottom-2 -right-2 bg-teal-500 text-white rounded-full p-1 shadow-md">
                    <CheckCircle className="w-5 h-5" />
                  </div>
                )}
              </button>
            );
          })}
        </div>
      </div>

      {/* ✍️ سوئال كىرگۈزۈش تاختىسى (چوڭ خەت + ئاپتوماتىك RTL/LTR) */}
      <div className="mb-8">
        <div className="flex justify-between items-center mb-4">
          <label className="text-base font-black text-gray-900 dark:text-white uppercase tracking-wider">
            2. Compose Global Prompt (سۇئال كىرگۈزۈڭ)
          </label>
          <button
            onClick={handleClear}
            disabled={!modelsInput && modelsOutput.length === 0}
            className="text-sm font-bold flex items-center gap-2 px-3 py-2 rounded-xl text-gray-500 hover:text-rose-500 dark:text-gray-400 hover:bg-rose-500/5 disabled:opacity-30 transition-all"
          >
            <RotateCcw className="w-4 h-4" />
            پاكىزلاش (Clear)
          </button>
        </div>
        
        <div className="relative">
          <textarea
            value={modelsInput}
            onChange={(e) => setModelsInput(e.target.value)}
            dir={isUyghurText(modelsInput) ? "rtl" : "ltr"}
            placeholder="يۇقىرى تېخنىكىلىق شىركەت ئۈچۈن سۈنئىي ئىدراك ۋە ئۇيغۇر تىلى تەرەققىياتى ھەققىدە پىلان تۈزۈپ بەر..."
            className={`w-full min-h-[160px] p-6 text-base text-gray-900 dark:text-gray-100 bg-white dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded-2xl focus:outline-none focus:ring-4 focus:ring-teal-500/20 focus:border-teal-500 shadow-inner leading-relaxed ${
              isUyghurText(modelsInput) ? "text-right font-medium" : "text-left"
            }`}
          />
        </div>
      </div>

      {/* ▶️ بەش مودېلنى تەڭ يوللاش كۇنۇپكىسى */}
      <button
        onClick={handleModelQuery}
        disabled={loading || selectedModels.length === 0 || !modelsInput.trim()}
        className={`w-full py-5 rounded-2xl font-black text-base tracking-wide text-white flex items-center justify-center gap-3 transition-all duration-300 ${
          loading || selectedModels.length === 0 || !modelsInput.trim()
            ? 'bg-slate-300 dark:bg-slate-800 text-gray-400 dark:text-gray-600 cursor-not-allowed'
            : 'bg-gradient-to-r from-teal-500 via-blue-600 to-indigo-600 shadow-xl shadow-teal-500/20 transform hover:-translate-y-0.5 active:translate-y-0'
        }`}
      >
        {loading ? (
          <>
            <div className="w-6 h-6 border-3 border-white border-t-transparent rounded-full animate-spin" />
            <span>ھەممە مودېللار ماس قەدەمدە ئىشلەۋاتىدۇ (Engines Processing...)</span>
          </>
        ) : (
          <>
            <Send className="w-5 h-5" />
            <span>تاللانغان {selectedModels.length} مودېلدىن تەڭ سوراش (Execute Comparison)</span>
          </>
        )}
      </button>

      {/* 💬 جاۋاب كۆزنەكلىرى (ئاپتوماتىك ئوڭدىن سولغا ۋە سولدىن ئوڭغا چىرايلىق ئايرىش) */}
      {modelsOutput && modelsOutput.length > 0 && (
        <div className="mt-12 pt-10 border-t border-gray-200 dark:border-slate-800">
          <h3 className="font-black text-gray-900 dark:text-white mb-6 text-xl flex items-center gap-2">
            <Sparkles className="w-6 h-6 text-indigo-500 animate-bounce" />
            3. Synchronized Stream Responses (مودېللارنىڭ جاۋابلىرى)
          </h3>
          
          <div className="grid grid-cols-1 xl:grid-cols-2 gap-6">
            {modelsOutput.map((result, index) => {
              const model = availableModels.find(m => m.id === result.modelId);
              if (!model) return null;
              
              const isOutputUyghur = isUyghurText(result.response);

              return (
                <div
                  key={index}
                  className="flex flex-col bg-white dark:bg-slate-800 rounded-2xl border border-gray-200 dark:border-slate-700/70 shadow-md hover:shadow-2xl transition-all duration-300 overflow-hidden"
                >
                  <div className="px-6 py-4 bg-slate-50 dark:bg-slate-800/40 border-b border-gray-100 dark:border-slate-700/50 flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      <span className="text-2xl">{model.icon}</span>
                      <div>
                        <h4 className="font-black text-base text-gray-900 dark:text-white">{model.name}</h4>
                        <p className="text-xs text-gray-400 font-bold">{model.provider}</p>
                      </div>
                    </div>
                  </div>
                  
                  {/* جاۋاب چىقىرىش قىسمى: ئۇيغۇرچە بولسا ئوڭدىن سولغا، باشقا تىلدا بولسا سولدىن ئوڭغا */}
                  <div 
                    dir={isOutputUyghur ? "rtl" : "ltr"}
                    className={`p-6 flex-1 text-gray-800 dark:text-gray-100 text-base whitespace-pre-wrap leading-relaxed overflow-y-auto max-h-[450px] ${
                      isOutputUyghur ? "text-right font-medium" : "text-left font-sans"
                    }`}
                  >
                    {result.response ? (
                      result.response
                    ) : (
                      <span className="text-gray-400 dark:text-gray-500 italic">No response received yet.</span>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* 🛠️ ئىختىيارىي مودېل قوشۇش كۆزنىكى (Popup Modal) */}
      {showCustomModal && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-50 p-4 animate-fadeIn">
          <div className="bg-white dark:bg-slate-800 rounded-3xl p-6 md:p-8 max-w-md w-full shadow-2xl border border-gray-100 dark:border-slate-700">
            <h3 className="text-xl font-black text-gray-900 dark:text-white mb-4 flex items-center gap-2">
              <PlusCircle className="w-6 h-6 text-indigo-500" />
              يېڭى مودېل قوشۇش (Custom API)
            </h3>
            
            <form onSubmit={handleAddCustomModel} className="space-y-4">
              <div>
                <label className="block text-xs font-bold mb-1.5 text-gray-600 dark:text-gray-400">مودېل نامى (Model Display Name)</label>
                <input 
                  type="text" required placeholder="مەسلەن: DeepSeek V3" 
                  value={customModelForm.name} onChange={e => setCustomModelForm({...customModelForm, name: e.target.value})}
                  className="w-full px-4 py-3 text-sm rounded-xl border border-gray-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-900 text-gray-900 dark:text-white"
                />
              </div>
              <div>
                <label className="block text-xs font-bold mb-1.5 text-gray-600 dark:text-gray-400">مودېل ID سى (Model ID)</label>
                <input 
                  type="text" required placeholder="مەسلەن: deepseek-chat" 
                  value={customModelForm.id} onChange={e => setCustomModelForm({...customModelForm, id: e.target.value})}
                  className="w-full px-4 py-3 text-sm rounded-xl border border-gray-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-900 text-gray-900 dark:text-white"
                />
              </div>
              <div>
                <label className="block text-xs font-bold mb-1.5 text-gray-600 dark:text-gray-400">شىركەت/پىروۋايدېر (Provider)</label>
                <input 
                  type="text" placeholder="مەسلەن: DeepSeek" 
                  value={customModelForm.provider} onChange={e => setCustomModelForm({...customModelForm, provider: e.target.value})}
                  className="w-full px-4 py-3 text-sm rounded-xl border border-gray-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-900 text-gray-900 dark:text-white"
                />
              </div>
              <div>
                <label className="block text-xs font-bold mb-1.5 text-gray-600 dark:text-gray-400">API ئادرېسى (Base URL) - ئىختىيارىي</label>
                <input 
                  type="url" placeholder="https://api.deepseek.com/v1" 
                  value={customModelForm.baseUrl} onChange={e => setCustomModelForm({...customModelForm, baseUrl: e.target.value})}
                  className="w-full px-4 py-3 text-sm rounded-xl border border-gray-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-900 text-gray-900 dark:text-white"
                />
              </div>
              
              <div className="flex gap-3 pt-4">
                <button 
                  type="submit" 
                  className="flex-1 py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-xl text-sm transition-colors"
                >
                  قوشۇش (Save Engine)
                </button>
                <button 
                  type="button" onClick={() => setShowCustomModal(false)}
                  className="flex-1 py-3 bg-gray-100 hover:bg-gray-200 dark:bg-slate-700 dark:hover:bg-slate-600 text-gray-700 dark:text-white font-bold rounded-xl text-sm transition-colors"
                >
                  بىكار قىلىش
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ModelsTab;