        {selectedMemberTeam === 'it' && <div className="h-full bg-gradient-to-r from-blue-500 to-indigo-600 rounded-t-full" />}
        {selectedMemberTeam === 'bigdata' && <div className="h-full bg-gradient-to-r from-amber-500 to-orange-600 rounded-t-full" />}
