import { useState } from "react";
import { useNavigate } from "react-router-dom";

// سىستېمىدىكى تەييار كارتون ئاۋاتارلار تىزىملىكى
const DEFAULT_AVATARS = [
  "https://api.dicebear.com/7.x/avataaars/svg?seed=Felix",
  "https://api.dicebear.com/7.x/avataaars/svg?seed=Aneka",
  "https://api.dicebear.com/7.x/avataaars/svg?seed=Jack",
  "https://api.dicebear.com/7.x/avataaars/svg?seed=晴太"
];

export default function Enroll() {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    phone: "",
    address: "",
    course: "",
    avatar: DEFAULT_AVATARS[0], // دەسلەپتە بىرىنچى ئاۋاتار تاللىنىدۇ
    isCustomImage: false // ئىشلەتكۈچى ئۆزى رەسىم يۈكلىدىمۇ يوق، شۇنى تەكشۈرۈش
  });

  const [avatarPreview, setAvatarPreview] = useState(DEFAULT_AVATARS[0]);

  // ئادەتتىكى تېكىست ۋە تاللانمىلارنى ئۆزگەرتىش
  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  // كومپيۇتېردىن ئۆزى رەسىم يۈكلىگەندە ئىجرا بولىدۇ
  const handleFileChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      setAvatarPreview(URL.createObjectURL(file));
      setFormData((prev) => ({ 
        ...prev, 
        avatar: file, 
        isCustomImage: true 
      }));
    }
  };

  // تەييار ئاۋاتار ئايكونلىرىدىن بىرىنى تاللىغاندا ئىجرا بولىدۇ
  const handleSelectDefaultAvatar = (avatarUrl) => {
    setAvatarPreview(avatarUrl);
    setFormData((prev) => ({ 
      ...prev, 
      avatar: avatarUrl, 
      isCustomImage: false 
    }));
  };

  // جەدۋەلنى يوللاش
  const handleSubmit = (e) => {
    e.preventDefault();

    const saveStudent = (avatarData) => {
      const newStudent = {
        name: formData.name,
        email: formData.email,
        phone: formData.phone,
        address: formData.address,
        course: formData.course,
        avatar: avatarData,
      };

      const students = JSON.parse(localStorage.getItem("students")) || [];
      students.push(newStudent);
      localStorage.setItem("students", JSON.stringify(students));
      navigate("/students");
    };

    // ئەگەر ئۆزى رەسىم يۈكلىگەن بولسا Base64 غا ئايلاندۇرۇش، بولمىسا تەييار لىنكنى ساقلاش
    if (formData.isCustomImage && formData.avatar instanceof File) {
      const reader = new FileReader();
      reader.onloadend = () => {
        saveStudent(reader.result);
      };
      reader.readAsDataURL(formData.avatar);
    } else {
      saveStudent(formData.avatar); // لىنكنى بىۋاسىتە ساقلايدۇ
    }
  };

  return (
    <section className="min-h-screen bg-gradient-to-br from-slate-50 to-blue-50 dark:from-slate-950 dark:to-slate-900 p-4 md:p-12 transition-colors duration-300" dir="rtl">
      <div className="max-w-2xl mx-auto bg-white dark:bg-slate-900 rounded-3xl shadow-xl border border-slate-100 dark:border-slate-800/60 p-6 md:p-10">
        
        {/* ئۈستۈنكى قىسىم: ئاۋاتار كۆرسىتىش رايونى */}
        <div className="text-center mb-8">
          <div className="relative inline-block">
            <img
              src={avatarPreview}
              alt="Avatar Preview"
              className="w-24 h-24 mx-auto mb-4 rounded-full shadow-lg object-cover border-4 border-white dark:border-slate-800 bg-slate-100 dark:bg-slate-800 transition-all duration-300"
            />
            {formData.isCustomImage && (
              <button
                type="button"
                onClick={() => handleSelectDefaultAvatar(DEFAULT_AVATARS[0])}
                className="absolute bottom-4 right-0 bg-rose-500 text-white rounded-full p-1 shadow hover:bg-rose-600 transition text-xs"
                title="رەسىمنى ئۆچۈرۈش"
              >
                ✕
              </button>
            )}
          </div>
          <h2 className="text-2xl md:text-3xl font-black text-slate-800 dark:text-slate-100">سۇپىغا تىزىملىتىش</h2>
          <p className="text-xs text-slate-500 dark:text-slate-400 mt-1">تۆۋەندىكى ئۇچۇرلارنى تولدۇرۇپ دەرسكە تىزىملىتىڭ</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-6">
          
          {/* 1. ئاۋاتار تاللاش تاختىسى */}
          <div className="space-y-3 bg-slate-50 dark:bg-slate-800/40 p-4 rounded-2xl border border-slate-100 dark:border-slate-800 text-right">
            <label className="block text-sm font-bold text-slate-700 dark:text-slate-300">
              👤 ئاۋاتار تاللاڭ ياكى رەسىم يۈكلەڭ
            </label>
            
            {/* تەييار ئاۋاتار ئايكونلىرى */}
            <div className="flex flex-wrap gap-4 items-center pt-1">
              {DEFAULT_AVATARS.map((avatarUrl, idx) => (
                <button
                  key={idx}
                  type="button"
                  onClick={() => handleSelectDefaultAvatar(avatarUrl)}
                  className={`w-12 h-12 rounded-full overflow-hidden border-2 transition-all p-0.5 bg-white dark:bg-slate-700 ${
                    !formData.isCustomImage && formData.avatar === avatarUrl
                      ? "border-blue-600 scale-110 shadow-md ring-2 ring-blue-100 dark:ring-blue-900"
                      : "border-transparent hover:border-slate-300 opacity-70 hover:opacity-100"
                  }`}
                >
                  <img src={avatarUrl} alt={`Avatar ${idx}`} className="w-full h-full object-cover" />
                </button>
              ))}

              {/* رەسىم يۈكلەش كۇنۇپكىسى (يوشۇرۇن چۈشۈرۈلگەن تىپى) */}
              <label className={`flex items-center justify-center w-12 h-12 rounded-full border-2 border-dashed text-xl cursor-pointer transition-all ${
                formData.isCustomImage 
                  ? "border-blue-600 bg-blue-50 text-blue-600 dark:bg-blue-950/40" 
                  : "border-slate-300 text-slate-400 hover:border-blue-500 hover:text-blue-500"
              }`}>
                📷
                <input
                  type="file"
                  name="avatar"
                  accept="image/*"
                  onChange={handleFileChange}
                  className="hidden"
                />
              </label>
            </div>
          </div>

          {/* 2. ئۇچۇر كىرگۈزۈش بۆلەكلىرى */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="space-y-1 text-right">
              <span className="text-xs font-bold text-slate-600 dark:text-slate-400">تولۇق ئىسمىڭىز</span>
              <input
                type="text"
                name="name"
                placeholder="مەسىلەن: ئەخمەتجان"
                value={formData.name}
                onChange={handleChange}
                required
                className="w-full bg-slate-50 dark:bg-slate-800 text-slate-800 dark:text-slate-100 border border-slate-200 dark:border-slate-700 rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition"
              />
            </div>

            <div className="space-y-1 text-right">
              <span className="text-xs font-bold text-slate-600 dark:text-slate-400">ئېلېكترونلۇق ئىلخەت</span>
              <input
                type="email"
                name="email"
                placeholder="example@mail.com"
                value={formData.email}
                onChange={handleChange}
                required
                className="w-full bg-slate-50 dark:bg-slate-800 text-slate-800 dark:text-slate-100 border border-slate-200 dark:border-slate-700 rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition"
              />
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="space-y-1 text-right">
              <span className="text-xs font-bold text-slate-600 dark:text-slate-400">تېلېفون نومۇرى</span>
              <input
                type="tel"
                name="phone"
                placeholder="05xxxxxxxxx"
                value={formData.phone}
                onChange={handleChange}
                required
                className="w-full bg-slate-50 dark:bg-slate-800 text-slate-800 dark:text-slate-100 border border-slate-200 dark:border-slate-700 rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition"
              />
            </div>

            <div className="space-y-1 text-right">
              <span className="text-xs font-bold text-slate-600 dark:text-slate-400">تۇرۇشلۇق ئادرېس</span>
              <input
                type="text"
                name="address"
                placeholder="مەسىلەن: ئىستانبۇل، تۈركىيە"
                value={formData.address}
                onChange={handleChange}
                className="w-full bg-slate-50 dark:bg-slate-800 text-slate-800 dark:text-slate-100 border border-slate-200 dark:border-slate-700 rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition"
              />
            </div>
          </div>

          {/* دەرس تاللاش قىسمى */}
          <div className="space-y-1 text-right">
            <span className="text-xs font-bold text-slate-600 dark:text-slate-400">تاللايدىغان لىكسىيە / دەرسلىك</span>
            <select
              name="course"
              value={formData.course}
              onChange={handleChange}
              className="w-full bg-slate-50 dark:bg-slate-800 text-slate-800 dark:text-slate-100 border border-slate-200 dark:border-slate-700 rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition cursor-pointer"
              required
            >
              <option value="">-- بىرەر دەرس تاللاڭ --</option>
              <option value="Python">پايتون پروگراممىلاشنىڭ ئاساسلىرى</option>
              <option value="Machine Learning">كىۋانت ماشىنا ئۆگىنىشى (QML)</option>
              <option value="Data Analysis">ئىلمىي تىل ئۆگىنىش ئۇسۇللىرى</option>
              <option value="AI Ethics">سۈنئىي ئەقىلنى ئەخلاقىي قوللىنىش</option>
            </select>
          </div>

          {/* ئۇچۇرلارنى ساقلاش كۇنۇپكىسى */}
          <div className="pt-2">
            <button
              type="submit"
              className="w-full md:w-auto px-8 py-3.5 bg-blue-600 hover:bg-blue-700 text-white font-bold rounded-xl shadow-md hover:shadow-lg hover:-translate-y-0.5 transition-all duration-150 text-sm"
            >
              🚀 تىزىملىتىشنى تاماملاش
            </button>
          </div>

        </form>
      </div>
    </section>
  );
}