// src/components/quantum/QuantumToolbar.jsx
import React from 'react';
import QuantumGate from './QuantumGate';

export default function QuantumToolbar() {
  const gates = [
    { type: 'H', label: 'Hadamard', color: 'bg-blue-500' },
    { type: 'X', label: 'Pauli-X', color: 'bg-red-500' },
    { type: 'Y', label: 'Pauli-Y', color: 'bg-green-500' },
    { type: 'Z', label: 'Pauli-Z', color: 'bg-purple-500' },
    { type: 'CNOT', label: 'Controlled-NOT', color: 'bg-indigo-600' },
    { type: 'SWAP', label: 'Swap', color: 'bg-orange-500' },
    { type: 'Measure', label: 'Measurement', color: 'bg-slate-700' },
  ];

  return (
    <div className="bg-white dark:bg-slate-900 p-4 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm">
      <h3 className="text-sm font-bold text-slate-500 dark:text-slate-400 mb-3 text-right">كۋانت دەرۋازىلىرى (سۆرەڭ)</h3>
      <div className="flex flex-wrap gap-3">
        {gates.map((gate) => (
          <QuantumGate key={gate.type} type={gate.type} label={gate.label} color={gate.color} />
        ))}
      </div>
    </div>
  );
}