// src/pages/QuantumAssistant.jsx
import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { HelpCircle, CheckCircle2, XCircle, ChevronDown, ChevronUp, AlertCircle, Sparkles, BookOpen } from 'lucide-react';
import defaultExercises from '../data/quantumExercises.js';

export default function QuantumAssistant({ data = [] }) {
  // تاللانغان سوئالنىڭ ئېچىلىش ھالىتى
  const [expandedId, setExpandedId] = useState(null);
  // ئوقۇغۇچى تاللىغان جاۋابلارنى ساقلاش ئامبىرى { [exerciseId]: optionIndex }
  const [selectedAnswers, setSelectedAnswers] = useState({});

  const exercises = Array.isArray(data) && data.length > 0 ? data : defaultExercises;

  const handleToggle = (id) => {
    setExpandedId(expandedId === id ? null : id);
  };

  const handleSelectOption = (exerciseId, optIdx) => {
    // ئەگەر ئاللىقاچان تاللاپ بولغان بولسا، قايتا ئۆزگەرتمەيدۇ (بىر قېتىملىق سىناق تۈزۈمى)
    if (selectedAnswers[exerciseId] !== undefined) return;
    
    setSelectedAnswers({
      ...selectedAnswers,
      [exerciseId]: optIdx
    });
  };

  return (
    <div className="text-right font-['UKIJ_Tuz','Microsoft_Uighur',sans-serif]" dir="rtl">
      {/* ماۋزۇ بوشلۇقى */}
      <div className="mb-8 border-b border-slate-200 dark:border-slate-800 pb-4">
        <h2 className="text-2xl font-black text-purple-600 dark:text-purple-400 flex items-center gap-2 justify-start">
          <span>🔬</span> ئالىي كۋانتۇم بىلىم سىناش تەجرىبىخانىسى
        </h2>
        <p className="text-sm text-slate-500 mt-1">
          ئۆگەنگەن بىلىملىرىڭىزنى سىناپ كۆرۈش ۋە مۇتەخەسسىسلەرنىڭ ھەقىقىي كۋانتۇم تەھلىللىرىنى كۆرۈش ئۈچۈن سوئاللارنى بېسىڭ.
        </p>
      </div>

      {exercises.length === 0 ? (
        <div className="text-center p-16 bg-slate-50 dark:bg-slate-900 rounded-2xl border border-dashed border-slate-200">
          <HelpCircle className="w-12 h-12 mx-auto mb-3 text-slate-300 animate-bounce" />
          <p className="text-slate-500">ھازىرچە ئىلغار مەشىقلەر يۈكلەنمىدى.</p>
        </div>
      ) : (
        <div className="space-y-5">
          {exercises.map((item, index) => {
            const isExpanded = expandedId === item.id;
            const userAnswer = selectedAnswers[item.id];
            const isCorrect = userAnswer === item.correctAnswer;

            return (
              <motion.div 
                key={item.id || index}
                layout="position"
                className={`bg-white dark:bg-slate-900 border rounded-3xl overflow-hidden shadow-sm transition-all duration-300 ${
                  isExpanded ? 'border-purple-500 ring-4 ring-purple-500/5' : 'border-slate-200/80 dark:border-slate-800 hover:border-slate-300'
                }`}
              >
                {/* سوئالنىڭ تېمىسى (بۇنى چەككەندە ئاستىدىكى قۇتا يۇمشاق يېيىلىدۇ) */}
                <div 
                  onClick={() => handleToggle(item.id)}
                  className="p-5 md:p-6 cursor-pointer flex items-start justify-between gap-4 select-none"
                >
                  <div className="flex items-start gap-3.5 flex-1">
                    <span className="w-10 h-10 bg-purple-50 dark:bg-purple-950/60 text-purple-600 dark:text-purple-400 rounded-xl flex items-center justify-center font-bold text-sm shrink-0 font-sans">
                      {index + 1}
                    </span>
                    <div>
                      <h3 className="font-black text-lg text-slate-900 dark:text-white leading-relaxed">
                        {item.question || "سوئال تېكىستى يوق"}
                      </h3>
                      {userAnswer !== undefined && (
                        <span className={`inline-flex items-center gap-1 text-xs font-bold mt-2 px-2.5 py-0.5 rounded-md ${
                          isCorrect ? 'bg-emerald-50 text-emerald-700 dark:bg-emerald-950/40 dark:text-emerald-400' : 'bg-rose-50 text-rose-700 dark:bg-rose-950/40 dark:text-rose-400'
                        }`}>
                          {isCorrect ? '✓ جاۋابىڭىز توغرا' : '✕ جاۋابىڭىز خاتا'}
                        </span>
                      )}
                    </div>
                  </div>
                  
                  {/* ئوڭ تەرەپتىكى كۆرسەتكۈچ بەلگە */}
                  <div className="text-slate-400 shrink-0 mt-1">
                    {isExpanded ? <ChevronUp className="w-5 h-5" /> : <ChevronDown className="w-5 h-5" />}
                  </div>
                </div>

                {/* 💡 يۇمشاق قىلىپ يېيىلىدىغان تاللانمىلار ۋە تەپسىلىي چۈشەندۈرۈش رايونى */}
                <AnimatePresence>
                  {isExpanded && (
                    <motion.div
                      initial={{ opacity: 0, height: 0 }}
                      animate={{ opacity: 1, height: "auto" }}
                      exit={{ opacity: 0, height: 0 }}
                      transition={{ duration: 0.3 }}
                      className="border-t border-slate-100 dark:border-slate-800 bg-slate-50/60 dark:bg-slate-900/30 p-6 pt-2"
                    >
                      {/* تاللانمىلار (A, B, C, D) */}
                      <div className="grid gap-3 sm:grid-cols-1 md:grid-cols-2 mt-4">
                        {item.options && item.options.map((option, optIdx) => {
                          // رەڭلەرنى ئاپتوماتىك ئايرىش لوگىكىسى
                          let optionStyle = "border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 text-slate-700 dark:text-slate-300 hover:bg-purple-50/50 dark:hover:bg-purple-950/20";
                          
                          if (userAnswer !== undefined) {
                            if (optIdx === item.correctAnswer) {
                              // توغرا جاۋاب يېشىل بولىدۇ
                              optionStyle = "border-emerald-500 bg-emerald-50/70 text-emerald-900 dark:bg-emerald-950/40 dark:text-emerald-300 font-bold";
                            } else if (userAnswer === optIdx) {
                              // ئوقۇغۇچى خاتا تاللىغان بولسا قىزىل بولىدۇ
                              optionStyle = "border-rose-400 bg-rose-50/70 text-rose-900 dark:bg-rose-950/40 dark:text-rose-300";
                            } else {
                              // تاللانمىغان باشقا قۇرۇق تاللانمىلار تۇتۇقلىشىدۇ
                              optionStyle = "border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 text-slate-400 opacity-60";
                            }
                          }

                          return (
                            <div 
                              key={optIdx}
                              onClick={() => handleSelectOption(item.id, optIdx)}
                              className={`p-4 rounded-2xl border text-base cursor-pointer transition-all flex items-center justify-between gap-3 ${optionStyle}`}
                            >
                              <span className="leading-relaxed">{option}</span>
                              <div className="flex items-center gap-2 shrink-0">
                                {userAnswer !== undefined && optIdx === item.correctAnswer && <CheckCircle2 className="w-4 h-4 text-emerald-500" />}
                                {userAnswer !== undefined && userAnswer === optIdx && optIdx !== item.correctAnswer && <XCircle className="w-4 h-4 text-rose-500" />}
                                <span className="w-6 h-6 rounded-xl bg-slate-100 dark:bg-slate-800 flex items-center justify-center text-xs text-slate-500 font-sans font-bold">
                                  {String.fromCharCode(65 + optIdx)}
                                </span>
                              </div>
                            </div>
                          );
                        })}
                      </div>

                      {/* 📝 جاۋاب بېرىلگەندىن كېيىن چىقىدىغان ئاكادېمىك تەھلىل بوشلۇقى */}
                      {userAnswer !== undefined && (
                        <motion.div 
                          initial={{ opacity: 0, y: 10 }}
                          animate={{ opacity: 1, y: 0 }}
                          className="mt-6 p-5 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl space-y-4 shadow-inner"
                        >
                          {/* نەزەرىيەۋى يېشىش */}
                          <div>
                            <h4 className="font-black text-purple-600 dark:text-purple-400 flex items-center gap-1.5 text-base">
                              <Sparkles className="w-4 h-4" /> مۇتەخەسسىس ئاكادېمىك تەھلىلى
                            </h4>
                            <p className="text-slate-600 dark:text-slate-300 mt-2 text-base leading-relaxed">
                              {item.explanation}
                            </p>
                          </div>

                          {/* ئەمەلىي كۋانت كودى ياكى فورمۇلا مىسالى */}
                          {item.example && (
                            <div className="pt-3 border-t border-slate-100 dark:border-slate-800">
                              <h5 className="font-bold text-sm text-slate-900 dark:text-white flex items-center gap-1.5 mb-2">
                                <BookOpen className="w-4 h-4 text-blue-500" /> تەجرىبىخانا ئەمەلىيەت مىسالى
                              </h5>
                              <pre className="p-3 bg-slate-950 text-emerald-400 font-mono text-xs rounded-xl overflow-x-auto text-left leading-relaxed" dir="ltr">
                                <code>{item.example}</code>
                              </pre>
                            </div>
                          )}
                        </motion.div>
                      )}
                    </motion.div>
                  )}
                </AnimatePresence>
              </motion.div>
            );
          })}
        </div>
      )}
    </div>
  );
}